    }

    /* 统计面板 */
    .stats-panel {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin: 10px 0;
    }

    .stat-box {
      background: #ffffff;
      border: 1px solid var(--gray-200);
      border-radius: 8px;
