<script>
    document.addEventListener('DOMContentLoaded', () => {
        const blocks = document.querySelectorAll('.math-block');
        const slots = document.querySelectorAll('.drop-slot');
        const cards = document.querySelectorAll('.scenario-card');
        const blockPool = document.getElementById('blockPool');
        const codeLock = document.getElementById('codeLock');
        const btnReset = document.getElementById('btnReset');
        const btnRun = document.getElementById('btnRun');
        const statusMsg = document.getElementById('statusMsg');
        const terminalModal = document.getElementById('terminalModal');
        const modalOverlay = document.getElementById('modalOverlay');
        const terminalBody = document.getElementById('terminalBody');
        const btnCloseTerminal = document.getElementById('btnCloseTerminal');

        let selectedBlock = null;

        // --- 交互：悬停情境卡片高亮对应的公式行 ---
        cards.forEach(card => {
            card.addEventListener('mouseenter', () => {
                const targetId = card.getAttribute('data-target');
                if (targetId === 'range') {
                    document.getElementById('slot-min').classList.add('highlight-target');
                    document.getElementById('slot-max').classList.add('highlight-target');
                } else {
                    document.getElementById(`slot-${targetId}`).classList.add('highlight-target');
                }
                card.classList.add('active-hover');
            });

            card.addEventListener('mouseleave', () => {
                slots.forEach(slot => slot.classList.remove('highlight-target'));
                card.classList.remove('active-hover');
            });
        });

        // --- 拖拽与点击选择逻辑 ---
        blocks.forEach(block => {
            // 拖拽开始
            block.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', block.id);
                block.classList.add('selected');
            });

            block.addEventListener('dragend', () => {
                block.classList.remove('selected');
            });

            // 点击选择（适配移动端/触屏）
            block.addEventListener('click', (e) => {
                e.stopPropagation();
                if (selectedBlock) {
                    selectedBlock.classList.remove('selected');
                }
                if (selectedBlock === block) {
                    selectedBlock = null;
                } else {
                    selectedBlock = block;
                    block.classList.add('selected');
                }
            });
        });

        slots.forEach(slot => {
            // 拖拽悬停
            slot.addEventListener('dragover', (e) => {
                e.preventDefault();
                slot.classList.add('drag-over');
            });

            slot.addEventListener('dragleave', () => {
                slot.classList.remove('drag-over');
            });

            // 拖拽释放
            slot.addEventListener('drop', (e) => {
                e.preventDefault();
                slot.classList.remove('drag-over');
                const blockId = e.dataTransfer.getData('text/plain');
                const block = document.getElementById(blockId);
                if (block) {
                    handlePlacement(block, slot);
                }
            });

            // 点击槽位放入或取出
            slot.addEventListener('click', (e) => {
                e.stopPropagation();
                if (selectedBlock) {
                    // 放入
                    handlePlacement(selectedBlock, slot);
                    selectedBlock.classList.remove('selected');
                    selectedBlock = null;
                } else if (slot.children.length > 0) {
                    // 取出
                    const block = slot.firstElementChild;
                    returnBlockToPool(block);
                    checkStatus();
                }
            });
        });

        // 点击空白处取消选择
        document.addEventListener('click', () => {
            if (selectedBlock) {
                selectedBlock.classList.remove('selected');
                selectedBlock = null;
            }
        });

        // 处理放置逻辑
        function handlePlacement(block, slot) {
            // 如果槽内已有积木，先退回
            if (slot.children.length > 0) {
                returnBlockToPool(slot.firstElementChild);
            }

            slot.appendChild(block);
            validateSlot(slot);
            checkStatus();
        }

        // 退回积木到池中
        function returnBlockToPool(block) {
            blockPool.appendChild(block);
            const parentSlot = block.parentElement;
            if (parentSlot && parentSlot.classList.contains('drop-slot')) {
                parentSlot.classList.remove('correct', 'incorrect');
            }
        }

        // 验证单个槽位
        function validateSlot(slot) {
            if (slot.children.length === 0) {
                slot.classList.remove('correct', 'incorrect');
                return;
            }
            const blockVal = slot.firstElementChild.getAttribute('data-val');
            const expectedVal = slot.getAttribute('data-expected');

            if (blockVal === expectedVal) {
                slot.classList.remove('incorrect');
                slot.classList.add('correct');
            } else {
                slot.classList.remove('correct');
                slot.classList.add('incorrect');
            }
        }

        // 检查整体状态
        function checkStatus() {
            let allCorrect = true;
            let filledCount = 0;

            slots.forEach(slot => {
                validateSlot(slot);
                if (slot.children.length > 0) {
                    filledCount++;
                    if (!slot.classList.contains('correct')) {
                        allCorrect = false;
                    }
                } else {
                    allCorrect = false;
                }
            });

            // 更新代码预览中的数值
            updateCodePreview();

            if (allCorrect) {
                codeLock.classList.add('unlocked');
                btnRun.removeAttribute('disabled');
                statusMsg.innerHTML = `<span class="status-success">🎉 翻译成功！数学模型已成功转化为计算机逻辑！</span>`;
            } else {
                codeLock.classList.remove('unlocked');
                btnRun.setAttribute('disabled', 'true');
                if (filledCount === slots.length) {
                    statusMsg.innerHTML = `<span style="color: #E74C3C;">❌ 模型中存在不匹配的数值，请重新检查。</span>`;
                } else {
                    statusMsg.innerHTML = `<span>已填入 ${filledCount}/${slots.length} 个条件...</span>`;
                }
            }
        }

        // 动态更新代码块中的数值
        function updateCodePreview() {
            const minVal = getSlotVal('slot-min');
            const maxVal = getSlotVal('slot-max');
            const r3Val = getSlotVal('slot-mod3');
            const r5Val = getSlotVal('slot-mod5');
            const r7Val = getSlotVal('slot-mod7');

            document.getElementById('code-min').innerText = minVal ? minVal : '1000';
            document.getElementById('code-max').innerText = maxVal ? (parseInt(maxVal) + 1) : '1101';
            document.getElementById('code-r3').innerText = r3Val ? r3Val : '?';
            document.getElementById('code-r5').innerText = r5Val ? r5Val : '?';
            document.getElementById('code-r7').innerText = r7Val ? r7Val : '?';
        }

        function getSlotVal(slotId) {
            const slot = document.getElementById(slotId);
            return slot.children.length > 0 ? slot.firstElementChild.getAttribute('data-val') : null;
        }

        // 重置按钮
        btnReset.addEventListener('click', () => {
            slots.forEach(slot => {
                if (slot.children.length > 0) {
                    returnBlockToPool(slot.firstElementChild);
                }
                slot.classList.remove('correct', 'incorrect');
            });
            checkStatus();
        });

        // --- 模拟终端运行动画 ---
        btnRun.addEventListener('click', () => {
            terminalBody.innerHTML = '';
            modalOverlay.classList.add('active');
            terminalModal.classList.add('active');

            const lines = [
                { text: '>>> python hanxin_solver.py', delay: 200 },
                { text: '正在初始化搜索范围: [1000, 1100]...', delay: 600 },
                { text: '开始逐个验证士兵人数 x ...', delay: 1000 },
                { text: 'x = 1000: 不满足条件', delay: 1200, fast: true },
                { text: 'x = 1001: 不满足条件', delay: 1250, fast: true },
                { text: 'x = 1010: 不满足条件', delay: 1300, fast: true },
                { text: 'x = 1030: 不满足条件', delay: 1350, fast: true },
                { text: 'x = 1050: 不满足条件', delay: 1400, fast: true },
                { text: '...', delay: 1500 },
                { text: '✨ 找到满足所有条件的数值！', delay: 1800, color: '#F1C40F' },
                { text: 'x = 1073 满足：', delay: 2000, color: '#2ECC71' },
                { text: '  - 1073 在 [1000, 1100] 范围内', delay: 2200, color: '#2ECC71' },
                { text: '  - 1073 % 3 == 2', delay: 2400, color: '#2ECC71' },
                { text: '  - 1073 % 5 == 3', delay: 2600, color: '#2ECC71' },
                { text: '  - 1073 % 7 == 2', delay: 2800, color: '#2ECC71' },
                { text: '👉 最终计算结果：韩信军队中共有 1073 名士兵。', delay: 3200, color: '#00E6FF', bold: true }
            ];

            lines.forEach(line => {
                setTimeout(() => {
                    const div = document.createElement('div');
                    div.className = 'terminal-line';
                    div.innerText = line.text;
                    if (line.color) div.style.color = line.color;
                    if (line.bold) div.style.fontWeight = 'bold';
                    terminalBody.appendChild(div);
                    terminalBody.scrollTop = terminalBody.scrollHeight;
                }, line.delay);
            });
        });

        function closeModal() {
            modalOverlay.classList.remove('active');
            terminalModal.classList.remove('active');
        }

        btnCloseTerminal.addEventListener('click', closeModal);
        modalOverlay.addEventListener('click', closeModal);
    });
</script>

