    .algo-block:hover {
      transform: translateY(-2px);
      box-shadow: 0 4px 8px rgba(0,0,0,0.1);
      border-color: var(--primary-color);
    }

    .algo-block.selected {
      border-color: var(--primary-color);
      background-color: #ebf5fb;
      box-shadow: 0 0 0 3px rgba(52, 152, 219, 0.3);
    }

    .algo-block.used {
      opacity: 0.4;
      cursor: not-allowed;
      pointer-events: none;
      background: #f5f5f5;
    }

    .block-badge {
      font-size: 11px;
      padding: 2px 6px;
      border-radius: 4px;
      color: white;
      font-weight: bold;
    }

    .badge-assign { background-color: #e67e22; }
    .badge-cond { background-color: #9b59b6; }

    .block-text {
      font-size: 13px;
      font-family: Consolas, Monaco, monospace;
      font-weight: bold;
    }

    /* 变量监视器 */
    .monitor-section {
      background: #f0f3f4;
      border-top: 2px solid #e0e0e0;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .monitor-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px;
    }

    .monitor-card {
      background: white;
      border-radius: 8px;
      padding: 10px;
      border: 1px solid #dcdde1;
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    .monitor-label {
      font-size: 11px;
      color: #7f8c8d;
      margin-bottom: 4px;
    }

    .monitor-value {
      font-size: 20px;
      font-weight: bold;
      color: var(--dark-bg);
      font-family: Consolas, monospace;
    }

    .cond-indicator {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
      margin-top: 4px;
    }

    .indicator-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background-color: #bdc3c7;
    }

    .indicator-dot.pass { background-color: var(--success-color); }
    .indicator-dot.fail { background-color: var(--error-color); }

    /* 运行日志 */
    .console-section {
      height: 120px;
      background: #1e272e;
      color: #0be881;
      font-family: Consolas, monospace;
      padding: 10px;
      font-size: 12px;
      overflow-y: auto;
      border-top: 2px solid #e0e0e0;
    }

    .console-line {
      margin-bottom: 4px;
      line-height: 1.4;
    }

    /* 流程图 SVG 样式 */
    svg {
      width: 100%;
      height: 100%;
    }

    .flow-slot {
      cursor: pointer;
      transition: all 0.3s ease;
    }

    .flow-slot:hover rect, .flow-slot:hover polygon {
      stroke: var(--primary-color);
      stroke-width: 3px;
    }

    .flow-slot.highlight rect, .flow-slot.highlight polygon {
      stroke: var(--primary-color);
      stroke-width: 3px;
      stroke-dasharray: none;
      animation: pulse 1.5s infinite;
    }

    @keyframes pulse {
      0% { opacity: 0.6; }
      50% { opacity: 1; }
      100% { opacity: 0.6; }
    }

    .slot-text {
      font-size: 11px;
      fill: #7f8c8d;
      text-anchor: middle;
      dominant-baseline: middle;
      pointer-events: none;
    }

    .slot-text.filled {
      font-size: 12px;
      fill: white;
      font-weight: bold;
    }

    /* 模拟控制栏 */
    .control-bar {
      background: var(--dark-bg);
      padding: 12px 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
    }

    .btn-group {
      display: flex;
      gap: 10px;
    }

    button {
