      border: none;
      border-radius: 6px;
      font-size: 14px;
      font-weight: bold;
      cursor: pointer;
      transition: all 0.2s ease;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .btn-primary {
      background-color: var(--primary-color);
      color: white;
    }

    .btn-primary:hover {
      background-color: var(--primary-dark);
    }

    .btn-success {
      background-color: var(--success-color);
      color: white;
    }

    .btn-success:hover {
      background-color: #27ae60;
    }

    .btn-danger {
      background-color: var(--error-color);
      color: white;
    }

    .btn-danger:hover {
      background-color: #c0392b;
    }

    button:disabled {
      background-color: #95a5a6;
      cursor: not-allowed;
      opacity: 0.6;
    }

    .speed-control {
      display: flex;
      align-items: center;
      gap: 10px;
      color: white;
      font-size: 13px;
    }

    .speed-control input {
      width: 100px;
      cursor: pointer;
    }

    /* 锁屏遮罩 */
    .lock-overlay {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(44, 62, 80, 0.85);
      backdrop-filter: blur(4px);
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      color: white;
      z-index: 10;
      transition: opacity 0.5s ease;
    }

    .lock-overlay.hidden {
      opacity: 0;
      pointer-events: none;
    }

    .lock-card {
      background: white;
      color: var(--dark-bg);
      padding: 30px;
      border-radius: 12px;
      text-align: center;
      box-shadow: 0 10px 30px rgba(0,0,0,0.3);
