      animation: float 2s infinite ease-in-out;
    }

    @keyframes float {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-10px); }
    }

    /* 成功提示动画 */
    .success-glow {
      animation: success-flash 0.5s ease-out;
    }

    @keyframes success-flash {
      0% { filter: drop-shadow(0 0 0px var(--success-color)); }
      50% { filter: drop-shadow(0 0 20px var(--success-color)); }
      100% { filter: drop-shadow(0 0 0px var(--success-color)); }
    }

    /* 节点高亮 */
    .active-node rect, .active-node polygon {
      stroke: var(--warning-color) !important;
      stroke-width: 4px !important;
      filter: drop-shadow(0 0 8px var(--warning-color));
    }
