                </div>
            </div>

            <!-- 控制按钮 -->
            <div class="control-bar">
                <button class="btn btn-reset" id="btn-reset">🔄 重置</button>
                <button class="btn btn-run" id="btn-run">▶ 运行程序</button>
            </div>
