<script>
    // 状态管理
    let currentTab = 'single'; // 'single', 'nested', 'parallel'
    let op1 = 'AND'; // 'AND', 'OR'
    let op2 = 'AND'; // 'AND', 'OR'

    // DOM 元素
    const tabSingle = document.getElementById('tab-single');
    const tabNested = document.getElementById('id-tab-nested');
    const tabParallel = document.getElementById('id-tab-parallel');
    const workspace = document.getElementById('blocks-workspace');
    const infoText = document.getElementById('info-text');
    const spriteBubble = document.getElementById('sprite-bubble');
    const outputScreen = document.getElementById('output-screen');
    const feedbackText = document.getElementById('feedback-text');
    const btnRun = document.getElementById('btn-run');
    const btnReset = document.getElementById('btn-reset');

    // 初始化渲染
    renderWorkspace();

    // 事件监听：选项卡切换
    tabSingle.addEventListener('click', () => switchTab('single'));
    tabNested.addEventListener('click', () => switchTab('nested'));
    tabParallel.addEventListener('click', () => switchTab('parallel'));

    // 运行与重置
    btnRun.addEventListener('click', runSimulation);
    btnReset.addEventListener('click', resetSimulation);

    function switchTab(tab) {
        currentTab = tab;
        [tabSingle, tabNested, tabParallel].forEach(btn => btn.classList.remove('active'));
        if (tab === 'single') tabSingle.classList.add('active');
        if (tab === 'nested') tabNested.classList.add('active');
        if (tab === 'parallel') tabParallel.classList.add('active');

        renderWorkspace();
        clearOutput();
    }

    // 渲染积木区
    function renderWorkspace() {
        workspace.innerHTML = '';

        // 外部循环积木
        const loopBlock = document.createElement('div');
