        loopBlock.style.borderLeftColor = '#e67e22';
        loopBlock.innerHTML = `重复执行 变量 <span style="background:rgba(0,0,0,0.15); padding:2px 6px; border-radius:4px;">i</span> 从 1000 到 1100`;
        workspace.appendChild(loopBlock);

        if (currentTab === 'single') {
            infoText.innerHTML = "在单一如果结构中，你可以通过下拉菜单修改<strong>逻辑算子</strong>。思考：要同时满足三个条件，应该用“且”还是“或”？";

            const ifBlock = document.createElement('div');
            ifBlock.className = 'scratch-block control-block';
            ifBlock.style.marginTop = '12px';

            // 构建组合条件 HTML
            ifBlock.innerHTML = `
                如果 
                <div class="scratch-block operator-block">
                    <span class="cond-tag">i ÷ 3 余 2</span>
                    <select class="operator-select" id="op1-select">
                        <option value="AND" ${op1 === 'AND' ? 'selected' : ''}>且 (AND)</option>
                        <option value="OR" ${op1 === 'OR' ? 'selected' : ''}>或 (OR)</option>
                    </select>
                    <span class="cond-tag">i ÷ 5 余 4</span>
                    <select class="operator-select" id="op2-select">
                        <option value="AND" ${op2 === 'AND' ? 'selected' : ''}>且 (AND)</option>
                        <option value="OR" ${op2 === 'OR' ? 'selected' : ''}>或 (OR)</option>
                    </select>
                    <span class="cond-tag">i ÷ 7 余 6</span>
                </div> 那么
                <br>
                <div class="scratch-block action-block">说出 i</div>
            `;
            workspace.appendChild(ifBlock);

            // 绑定下拉框事件
            document.getElementById('op1-select').addEventListener('change', (e) => {
                op1 = e.target.value;
                clearOutput();
            });
            document.getElementById('op2-select').addEventListener('change', (e) => {
                op2 = e.target.value;
                clearOutput();
            });

        } else if (currentTab === 'nested') {
            infoText.innerHTML = "<strong>多重嵌套如果</strong>：只有当外层条件满足时，才会判断内层条件。这在逻辑上等同于什么算子？";

            const if1 = document.createElement('div');
            if1.className = 'scratch-block control-block';
            if1.style.marginTop = '12px';
            if1.innerHTML = `如果 <div class="scratch-block operator-block"><span class="cond-tag">i ÷ 3 余 2</span></div> 那么`;

            const if2 = document.createElement('div');
            if2.className = 'scratch-block control-block-nested';
            if2.innerHTML = `如果 <div class="scratch-block operator-block"><span class="cond-tag">i ÷ 5 余 4</span></div> 那么`;

            const if3 = document.createElement('div');
            if3.className = 'scratch-block control-block-nested';
            if3.innerHTML = `如果 <div class="scratch-block operator-block"><span class="cond-tag">i ÷ 7 余 6</span></div> 那么<br><div class="scratch-block action-block" style="margin-left:12px;">说出 i</div>`;

            if2.appendChild(if3);
            if1.appendChild(if2);
            workspace.appendChild(if1);

        } else if (currentTab === 'parallel') {
            infoText.innerHTML = "<strong>三个并列如果</strong>：每个条件都是独立判断的。如果一个数字满足多个条件，会发生什么？";

            const container = document.createElement('div');
            container.style.width = '100%';
            container.style.marginTop = '12px';

            const if1 = document.createElement('div');
            if1.className = 'scratch-block control-block';
            if1.innerHTML = `如果 <div class="scratch-block operator-block"><span class="cond-tag">i ÷ 3 余 2</span></div> 那么<br><div class="scratch-block action-block">说出 i</div>`;

            const if2 = document.createElement('div');
            if2.className = 'scratch-block control-block';
            if2.innerHTML = `如果 <div class="scratch-block operator-block"><span class="cond-tag">i ÷ 5 余 4</span></div> 那么<br><div class="scratch-block action-block">说出 i</div>`;

            const if3 = document.createElement('div');
            if3.className = 'scratch-block control-block';
            if3.innerHTML = `如果 <div class="scratch-block operator-block"><span class="cond-tag">i ÷ 7 余 6</span></div> 那么<br><div class="scratch-block action-block">说出 i</div>`;

            container.appendChild(if1);
            container.appendChild(if2);
            container.appendChild(if3);
            workspace.appendChild(container);
        }
    }

    // 清理输出
    function clearOutput() {
        outputScreen.innerHTML = '<span style="color: #888;">等待程序运行...</span>';
        spriteBubble.innerHTML = '点击“运行程序”，帮我找出那个神秘的数字吧！';
        feedbackText.innerHTML = '请先选择逻辑结构，然后点击下方运行按钮进行测试。';
        feedbackText.className = 'feedback-content';
    }

    // 重置
    function resetSimulation() {
        op1 = 'AND';
        op2 = 'AND';
        currentTab = 'single';
        [tabSingle, tabNested, tabParallel].forEach(btn => btn.classList.remove('active'));
        tabSingle.classList.add('active');
        renderWorkspace();
        clearOutput();
    }

    // 运行模拟
    function runSimulation() {
        outputScreen.innerHTML = '<span style="color: #00ffcc;">正在扫描区间 1000 ~ 1100...</span>';
        spriteBubble.innerHTML = '让我想想... 正在逐个检查数字...';

        btnRun.disabled = true;
        btnReset.disabled = true;

        // 模拟计算延迟，增强教学仪式感
        setTimeout(() => {
            executeLogic();
            btnRun.disabled = false;
            btnReset.disabled = false;
        }, 1000);
    }

    // 核心逻辑执行
    function executeLogic() {
        let results = [];
        let isParallel = (currentTab === 'parallel');

        for (let i = 1000; i <= 1100; i++) {
            let c1 = (i % 3 === 2);
            let c2 = (i % 5 === 4);
            let c3 = (i % 7 === 6);

            if (currentTab === 'single') {
                // 模拟 Scratch 从左到右的结合律
                let step1 = false;
                if (op1 === 'AND') {
                    step1 = c1 && c2;
                } else {
                    step1 = c1 || c2;
                }

                let finalStep = false;
                if (op2 === 'AND') {
                    finalStep = step1 && c3;
                } else {
                    finalStep = step1 || c3;
                }

                if (finalStep) {
                    results.push(i);
                }
            } else if (currentTab === 'nested') {
                // 嵌套如果等同于 AND
                if (c1) {
                    if (c2) {
                        if (c3) {
                            results.push(i);
                        }
                    }
                }
            } else if (isParallel) {
                // 并列如果：每个条件独立判断，可能重复添加同一个数
                if (c1) results.push(i);
                if (c2) results.push(i);
                if (c3) results.push(i);
            }
        }

        displayResults(results);
    }

    // 展示结果与诊断
    function displayResults(results) {
        outputScreen.innerHTML = '';

        if (results.length === 0) {
            outputScreen.innerHTML = '<span style="color: #ff4757;">没有找到符合条件的数字。</span>';
            spriteBubble.innerHTML = '奇怪，一个数字都没找到，是不是条件太苛刻了？';
            feedbackText.innerHTML = '<span class="status-error">❌ 逻辑错误：</span>当前逻辑无法筛选出任何数字。请重新检查你的逻辑算子。';
            return;
        }

        // 渲染数字标签
        results.forEach(num => {
            const span = document.createElement('span');
            span.className = 'number-tag';
            if (num === 1049) {
                span.classList.add('correct');
            }
            span.innerText = num;
            outputScreen.appendChild(span);
        });

        // 诊断逻辑
        if (currentTab === 'single') {
            if (op1 === 'AND' && op2 === 'AND') {
                showSuccess();
            } else {
                showTooManyWarning("条件过于宽松，请检查逻辑算子！");
            }
        } else if (currentTab === 'nested') {
            showSuccess();
        } else if (currentTab === 'parallel') {
            showParallelWarning();
        }
    }

    // 成功反馈
    function showSuccess() {
        spriteBubble.innerHTML = '🎉 太棒了！我找到了唯一的神秘数字：<strong>1049</strong>！';
        feedbackText.innerHTML = `
            <span class="status-success">✅ 逻辑完全正确！</span><br>
            在 1000 到 1100 之间，只有 <strong>1049</strong> 同时满足三个余数条件。<br>
            <small>💡 思考：多重嵌套的“如果”在效果上等同于使用“且 (AND)”连接所有条件。</small>
        `;
    }

    // 过于宽松反馈
    function showTooManyWarning(msg) {
        spriteBubble.innerHTML = '哎呀，输出了太多数字！里面混进了好多错误答案。';
        feedbackText.innerHTML = `
            <span class="status-error">⚠️ ${msg}</span><br>
            你使用了<strong>“或 (OR)”</strong>算子。这导致只要满足其中一部分条件，数字就会被输出。<br>
            我们需要寻找<strong>同时满足</strong>三个条件的数，请尝试将算子改为<strong>“且 (AND)”</strong>。
        `;
    }

    // 并列如果反馈
    function showParallelWarning() {
        spriteBubble.innerHTML = '哇！怎么输出了这么多数字？而且 1049 好像出现了好几次？';
        feedbackText.innerHTML = `
            <span class="status-error">⚠️ 逻辑错误：并列“如果”导致逻辑混乱</span><br>
            1. 并列的“如果”是<strong>独立运行</strong>的。只要满足任意一个条件，数字就会被输出。<br>
            2. 像 1049 这样同时满足三个条件的数字，会被三个“如果”分别输出一次，导致<strong>重复输出</strong>！
        `;
    }
