  <script>
    // 状态管理
    const state = {
      running: false,
      pos1: 0,       // 0 到 100
      pos2: 0,       // 0 到 14 (代表 0, 7, 14... 98)
      checks1: 0,
      checks2: 0,
      speed: 200,    // 毫秒/步
      timer: null
    };

    // DOM 元素
    const svg = document.getElementById('track-svg');
    const ticksGroup = document.getElementById('ticks-group');
    const car1 = document.getElementById('car1');
    const car2 = document.getElementById('car2');
    const ripple1 = document.getElementById('ripple1');
    const ripple2 = document.getElementById('ripple2');
    const counter1 = document.getElementById('counter1');
    const counter2 = document.getElementById('counter2');
    const bar1 = document.getElementById('bar1');
    const bar2 = document.getElementById('bar2');
    const bar1Text = document.getElementById('bar1-text');
    const bar2Text = document.getElementById('bar2-text');
    const badge = document.getElementById('efficiency-badge');

    const btnStart = document.getElementById('btn-start');
    const btnPause = document.getElementById('btn-pause');
    const btnReset = document.getElementById('btn-reset');
    const speedSlider = document.getElementById('speed-slider');

    // 跑道物理参数
    const startX = 30;
    const endX = 460;
    const trackWidth = endX - startX; // 430px

    // 初始化跑道刻度
    function initTicks() {
      ticksGroup.innerHTML = '';

      // 跑道1：0-100 刻度 (每10个标数字)
      for (let i = 0; i <= 100; i++) {
        const x = startX + (i / 100) * trackWidth;
        const isMajor = i % 10 === 0;

        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x);
        line.setAttribute('x2', x);
        line.setAttribute('y1', isMajor ? 42 : 46);
        line.setAttribute('y2', 50);
        line.setAttribute('stroke', isMajor ? '#64748b' : '#cbd5e1');
        line.setAttribute('stroke-width', isMajor ? '1.5' : '1');
        ticksGroup.appendChild(line);

        if (isMajor) {
          const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          text.setAttribute('x', x);
          text.setAttribute('y', 36);
          text.setAttribute('font-size', '8');
          text.setAttribute('fill', '#64748b');
          text.setAttribute('text-anchor', 'middle');
          text.textContent = i;
          ticksGroup.appendChild(text);
        }
      }

      // 跑道2：7的倍数刻度 (0, 7, 14... 98)
      for (let i = 0; i <= 14; i++) {
        const val = i * 7;
        const x = startX + (val / 100) * trackWidth;

        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x);
        line.setAttribute('x2', x);
        line.setAttribute('y1', 160);
        line.setAttribute('y2', 168);
        line.setAttribute('stroke', 'var(--primary-green)');
        line.setAttribute('stroke-width', '1.5');
        ticksGroup.appendChild(line);

        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.setAttribute('x', x);
        text.setAttribute('y', 178);
        text.setAttribute('font-size', '8');
        text.setAttribute('font-weight', 'bold');
        text.setAttribute('fill', 'var(--primary-green)');
        text.setAttribute('text-anchor', 'middle');
        text.textContent = val;
        ticksGroup.appendChild(text);
      }
    }

    // 触发检测波纹效果
    function triggerRipple(rippleEl, x, y, isTarget) {
      rippleEl.setAttribute('cx', x);
      rippleEl.setAttribute('cy', y);
      rippleEl.setAttribute('stroke', isTarget ? 'var(--primary-green)' : 'var(--primary-red)');

      // 重置动画
      rippleEl.setAttribute('r', '0');
      rippleEl.setAttribute('opacity', '1');

      // 强制重绘以触发动画
      rippleEl.classList.remove('ripple');
      void rippleEl.offsetWidth; 
      rippleEl.classList.add('ripple');
    }

    // 更新界面
    function updateUI() {
      // 1. 更新小车位置
      const x1 = startX + (state.pos1 / 100) * trackWidth;
      car1.setAttribute('transform', `translate(${x1}, 50)`);

      const val2 = state.pos2 * 7;
      const x2 = startX + (val2 / 100) * trackWidth;
      car2.setAttribute('transform', `translate(${x2}, 160)`);

      // 2. 更新计数器
      counter1.textContent = `已检测: ${state.checks1} 次`;
      counter2.textContent = `已检测: ${state.checks2} 次`;

      // 3. 更新柱状图 (最大高度 130px 对应 110 次检测)
      const maxChartHeight = 130;
      const scale = maxChartHeight / 110;

      const h1 = state.checks1 * scale;
      bar1.setAttribute('height', h1);
      bar1.setAttribute('y', 150 - h1);
      bar1Text.textContent = state.checks1;
      bar1Text.setAttribute('y', 145 - h1);

      const h2 = state.checks2 * scale;
      bar2.setAttribute('height', h2);
      bar2.setAttribute('y', 150 - h2);
      bar2Text.textContent = state.checks2;
      bar2Text.setAttribute('y', 145 - h2);

      // 4. 勋章展示逻辑 (当优化算法运行完毕时即可展示)
      if (state.pos2 >= 14) {
        badge.classList.add('show');
      } else {
        badge.classList.remove('show');
      }
    }

    // 单步执行逻辑
    function step() {
      if (!state.running) return;

      let hasActive = false;

      // 普通小车：每次走 1 格，检测 1 次
      if (state.pos1 <= 100) {
        state.checks1 = state.pos1 + 1;
        const x = startX + (state.pos1 / 100) * trackWidth;
        const isMultipleOf7 = state.pos1 % 7 === 0;
        triggerRipple(ripple1, x, 50, isMultipleOf7);

        state.pos1++;
        hasActive = true;
      }

      // 优化小车：每次走 7 格，检测 1 次
      if (state.pos2 <= 14) {
        state.checks2 = state.pos2 + 1;
        const val = state.pos2 * 7;
        const x = startX + (val / 100) * trackWidth;
        triggerRipple(ripple2, x, 160, true); // 每次落点都是7的倍数，必然成功

        state.pos2++;
        hasActive = true;
      }

      updateUI();

      if (hasActive) {
        state.timer = setTimeout(step, state.speed);
      } else {
        // 全部运行完毕
        state.running = false;
        btnStart.disabled = true;
        btnPause.disabled = true;
      }
    }

    // 控制函数
    function startSimulation() {
      if (state.running) return;
      state.running = true;
