                    <!-- 书籍将由JS动态生成 -->
                </div>
            </div>

            <!-- 控制按钮 -->
            <div class="control-panel">
                <button class="btn btn-random" id="btnRandom">
                    🎲 无序乱翻
                </button>
                <button class="btn btn-seq" id="btnSeq">
                    🔍 按序依次翻
                </button>
                <button class="btn btn-reset" id="btnReset">
                    🔄 重置
                </button>
            </div>
        </div>

        <!-- 右侧：数据与卡片 -->
        <div class="right-panel">
            <!-- 数据看板 -->
            <div class="data-board">
                <h3 id="strategyTitle">当前策略：等待选择</h3>
                <div class="stats-grid">
                    <div class="stat-card">
                        <div class="stat-label">已检查书籍</div>
                        <div class="stat-value" id="statChecked">0 / 11</div>
                    </div>
                    <div class="stat-card">
                        <div class="stat-label">重复检查次数</div>
                        <div class="stat-value highlight-red" id="statDuplicate">0</div>
                    </div>
                    <div class="stat-card">
                        <div class="stat-label">遗漏书籍数量</div>
                        <div class="stat-value" id="statMissed">11</div>
                    </div>
                    <div class="stat-card">
                        <div class="stat-label">遗漏率</div>
                        <div class="stat-value highlight-red" id="statMissRate">100%</div>
                    </div>
                </div>
            </div>

