<script>
    // 书籍数据定义
    const booksData = [
        { id: 300, year: 2011, price: 25.5 },
        { id: 301, year: 2012, price: 28.8 }, // 目标书籍: 2012%4==0, 28.8尾数是8
        { id: 302, year: 2015, price: 18.0 },
        { id: 303, year: 2016, price: 15.0 }, // 年份能被4整除，但价格尾数不是8
        { id: 304, year: 2003, price: 45.8 }, // 价格尾数是8，但年份不能被4整除
        { id: 305, year: 2018, price: 18.8 },
        { id: 306, year: 2020, price: 24.3 },
        { id: 307, year: 2011, price: 19.8 },
        { id: 308, year: 2004, price: 30.2 },
        { id: 309, year: 2021, price: 28.8 },
        { id: 310, year: 2008, price: 35.4 }
    ];

    const bookshelf = document.getElementById('bookshelf');
    const btnRandom = document.getElementById('btnRandom');
    const btnSeq = document.getElementById('btnSeq');
    const btnReset = document.getElementById('btnReset');
    const scanLine = document.getElementById('scanLine');
    const pointerHand = document.getElementById('pointerHand');

    const statChecked = document.getElementById('statChecked');
    const statDuplicate = document.getElementById('statDuplicate');
    const statMissed = document.getElementById('statMissed');
    const statMissRate = document.getElementById('statMissRate');
    const strategyTitle = document.getElementById('strategyTitle');
    const inspectorDetails = document.getElementById('inspectorDetails');

    let isRunning = false;
    let checkedSet = new Set();
    let duplicateCount = 0;

    // 初始化生成书籍
    function initBooks() {
        bookshelf.innerHTML = '';
        booksData.forEach((book, index) => {
            const bookDiv = document.createElement('div');
            bookDiv.className = 'book';
            bookDiv.dataset.index = index;
            bookDiv.innerHTML = `
                <span class="book-index">${book.id}</span>
                <span class="book-label">科幻书</span>
            `;
            bookDiv.addEventListener('click', () => inspectBook(index));
            bookshelf.appendChild(bookDiv);
        });
        resetStats();
    }

    // 重置统计数据和状态
    function resetStats() {
        checkedSet.clear();
        duplicateCount = 0;
        isRunning = false;

        // 恢复按钮
        btnRandom.disabled = false;
        btnSeq.disabled = false;

        // 隐藏辅助动画元素
        scanLine.style.display = 'none';
        pointerHand.style.display = 'none';

        // 更新界面
        strategyTitle.textContent = '当前策略：等待选择';
        strategyTitle.style.color = 'var(--dark-color)';
        statChecked.textContent = '0 / 11';
        statDuplicate.textContent = '0';
        statMissed.textContent = '11';
        statMissRate.textContent = '100%';
        statMissRate.className = 'stat-value highlight-red';

        // 恢复书籍样式
        const books = document.querySelectorAll('.book');
        books.forEach(book => {
            book.className = 'book';
            book.style.transform = 'none';
        });

        inspectorDetails.innerHTML = '点击上方书架上的任意一本书，查看它的出版年份和价格，看看它是否符合我们的目标条件！';
    }

    // 探测单本书籍属性
    function inspectBook(index) {
        if (isRunning) return; // 演示运行时禁止手动点击

        const book = booksData[index];
        const isYearDiv4 = book.year % 4 === 0;
        const isPriceEnd8 = book.price.toFixed(1).endsWith('8');
        const isTarget = isYearDiv4 && isPriceEnd8;

        let resultHTML = `
            <strong>索书号：</strong><span>${book.id}</span><br>
            <strong>出版年份：</strong>${book.year}年 (${isYearDiv4 ? '✅ 能被4整除' : '❌ 不能被4整除'})<br>
            <strong>书籍价格：</strong>${book.price}元 (${isPriceEnd8 ? '✅ 尾数是8' : '❌ 尾数不是8'})<br>
            <hr style="margin:8px 0; border:none; border-top:1px solid #cbd5e0;">
            <strong>结论：</strong> ${isTarget ? '<span style="color:var(--success-color)">🌟 完美符合条件！这就是我们要找的书！</span>' : '<span style="color:var(--danger-color)">❌ 不符合条件</span>'}
        `;
        inspectorDetails.innerHTML = resultHTML;

        // 高亮被点击的书
        const books = document.querySelectorAll('.book');
        books.forEach(b => b.classList.remove('active-scan'));
        books[index].classList.add('active-scan');
    }

    // 顺序扫描策略
    function runSequential() {
        if (isRunning) return;
        resetStats();
        isRunning = true;
        btnRandom.disabled = true;
        btnSeq.disabled = true;
        strategyTitle.textContent = '当前策略：按序依次翻 (顺序寻找)';
        strategyTitle.style.color = 'var(--primary-color)';

        scanLine.style.display = 'block';
        scanLine.style.left = '0%';

        let currentIndex = 0;
        const books = document.querySelectorAll('.book');

        const interval = setInterval(() => {
            if (currentIndex >= booksData.length) {
                clearInterval(interval);
                scanLine.style.display = 'none';
                isRunning = false;
                btnReset.disabled = false;
                return;
            }

            // 移动扫描线
            const bookElement = books[currentIndex];
            const rect = bookElement.getBoundingClientRect();
            const shelfRect = bookshelf.getBoundingClientRect();
            const relativeLeft = rect.left - shelfRect.left + (rect.width / 2);
            scanLine.style.left = `${relativeLeft}px`;

            // 标记当前检查的书籍
            bookElement.classList.add('active-scan');

            // 延迟一下变绿，模拟翻阅过程
            setTimeout(() => {
                bookElement.classList.remove('active-scan');
                bookElement.classList.add('state-checked');
                checkedSet.add(currentIndex);
                updateDashboard();
            }, 150);

            currentIndex++;
        }, 450);
    }

    // 无序乱翻策略
    function runRandom() {
        if (isRunning) return;
        resetStats();
        isRunning = true;
        btnRandom.disabled = true;
        btnSeq.disabled = true;
        strategyTitle.textContent = '当前策略：无序乱翻 (随机寻找)';
        strategyTitle.style.color = '#e67e22';

        pointerHand.style.display = 'block';

        let steps = 0;
        const maxSteps = 11; // 同样给11次机会，对比效率
        const books = document.querySelectorAll('.book');

        const interval = setInterval(() => {
            if (steps >= maxSteps) {
                clearInterval(interval);
                pointerHand.style.display = 'none';

                // 标记未被翻阅到的遗漏书籍
                books.forEach((book, idx) => {
                    if (!checkedSet.has(idx)) {
                        book.classList.add('state-missed');
                    }
                });

                isRunning = false;
                return;
            }

            // 随机选择一本书
            const randomIndex = Math.floor(Math.random() * booksData.length);
            const bookElement = books[randomIndex];

            // 移动指针手势
            const rect = bookElement.getBoundingClientRect();
            const shelfRect = bookshelf.getBoundingClientRect();
            const relativeLeft = rect.left - shelfRect.left + (rect.width / 2) - 15;
            pointerHand.style.left = `${relativeLeft}px`;
            pointerHand.style.top = `-35px`;

            // 检查是否重复
