                bookElement.classList.add('state-duplicate');
                setTimeout(() => {
                    bookElement.classList.remove('state-duplicate');
                }, 300);
            } else {
                checkedSet.add(randomIndex);
                bookElement.classList.add('state-checked');
            }

            updateDashboard();
            steps++;
        }, 600);
    }

    // 更新数据看板
    function updateDashboard() {
        const checkedCount = checkedSet.size;
        const totalBooks = booksData.length;
        const missedCount = totalBooks - checkedCount;
