        statChecked.textContent = `${checkedCount} / ${totalBooks}`;
        statDuplicate.textContent = duplicateCount;
        statMissed.textContent = missedCount;
        statMissRate.textContent = `${missRate}%`;

        if (missRate === 0) {
            statMissRate.className = 'stat-value highlight-green';
        } else {
            statMissRate.className = 'stat-value highlight-red';
        }
    }

