<script>
    const startNum = 1000;
    const endNum = 1010;
    let testedCount = 0;
    let isRunning = false;
    const results = {};

    const grid = document.getElementById('number-grid');
    const statusBox = document.getElementById('status-box');
    const currentTestNumText = document.getElementById('current-test-num');
    const leftValText = document.getElementById('left-val');
    const rightValText = document.getElementById('right-val');
    const alertLight = document.getElementById('alert-light');
    const alertText = document.getElementById('alert-text');
    const balanceBeam = document.getElementById('balance-beam');
    const mathPanel = document.getElementById('math-panel');
    const conclusionText = document.getElementById('conclusion-text');

    // 初始化数字卡片
    for (let i = startNum; i <= endNum; i++) {
        const card = document.createElement('div');
        card.className = 'num-card';
        card.id = `card-${i}`;
        card.innerText = i;
        card.addEventListener('click', () => {
            if (isRunning) return;
            testNumber(i);
        });
        grid.appendChild(card);
        results[i] = false;
    }

    // 测试单个数字
    function testNumber(num) {
        // 移除其他卡片的激活状态
        document.querySelectorAll('.num-card').forEach(c => c.classList.remove('active'));

        const card = document.getElementById(`card-${num}`);
        card.classList.add('active');
        card.classList.add('checked-fail');

        currentTestNumText.textContent = num;

        // 计算余数
        const rem3 = num % 3;
        const rem6 = num % 6;

        leftValText.textContent = `${num} ÷ 3 余 ${rem3}`;
        rightValText.textContent = `${num} ÷ 6 余 ${rem6}`;

        // 判断条件
        const cond1 = (rem3 === 2);
        const cond2 = (rem6 === 1);

        // 更新天平视觉效果
        if (cond1 && !cond2) {
            // 左盘满足，右盘不满足 -> 偏向左边
            balanceBeam.setAttribute('transform', 'rotate(-4, 200, 100)');
            setAlert('冲突', '#ef4444');
        } else if (!cond1 && cond2) {
            // 右盘满足，左盘不满足 -> 偏向右边
            balanceBeam.setAttribute('transform', 'rotate(4, 200, 100)');
            setAlert('冲突', '#ef4444');
        } else {
            // 都不满足 -> 剧烈晃动表示完全不匹配
            balanceBeam.setAttribute('transform', 'rotate(0, 200, 100)');
            balanceBeam.classList.add('shaking');
            setTimeout(() => balanceBeam.classList.remove('shaking'), 300);
            setAlert('不符', '#94a3b8');
        }

        // 记录测试进度
        if (!results[num]) {
            results[num] = true;
            testedCount = Object.values(results).filter(v => v).length;
        }

        updateStatus(num, rem3, rem6);
    }

    function setAlert(text, color) {
        alertLight.setAttribute('fill', color);
        alertText.textContent = text;
        alertText.setAttribute('fill', '#ffffff');
    }

    function updateStatus(num, rem3, rem6) {
        let html = `<strong>正在检测数字 ${num}：</strong><br>`;
        html += `• 条件一（除以3余2）：${num} % 3 = ${rem3} ${rem3 === 2 ? '✅' : '❌'}<br>`;
        html += `• 条件二（除以6余1）：${num} % 6 = ${rem6} ${rem6 === 1 ? '✅' : '❌'}<br>`;
        html += `<strong>结果：</strong> 两个条件无法同时满足！`;
        statusBox.innerHTML = html;

        checkCompletion();
    }

    function checkCompletion() {
        if (testedCount === (endNum - startNum + 1)) {
            conclusionText.innerHTML = `<strong>全部检测完毕！未找到任何符合条件的数字。这证明了：该问题在此区间内【无解】！</strong>`;
            conclusionText.style.color = 'var(--accent-color)';
            statusBox.innerHTML = `<strong>🎉 遍历完毕！</strong><br>我们依次检测了 1000 到 1010 的所有数字，发现<strong>没有一个数字</strong>能同时满足这两个条件。这说明枚举算法不仅能帮我们“找到答案”，在没有答案时，它还能帮我们<strong>“确定无解”</strong>！`;
        }
    }

    // 自动一键枚举
    async function autoRun() {
        if (isRunning) return;
        isRunning = true;
        document.getElementById('btn-auto').disabled = true;
        document.getElementById('btn-auto').style.opacity = 0.5;

        for (let i = startNum; i <= endNum; i++) {
            testNumber(i);
            await new Promise(resolve => setTimeout(resolve, 600));
        }

        isRunning = false;
        document.getElementById('btn-auto').disabled = false;
        document.getElementById('btn-auto').style.opacity = 1;
    }

    // 重置
    function reset() {
        if (isRunning) return;
        testedCount = 0;
        for (let i = startNum; i <= endNum; i++) {
            results[i] = false;
            const card = document.getElementById(`card-${i}`);
