            slot.className = 'pin-slot';
            slot.textContent = '-';
            pinContainer.appendChild(slot);
        }
        updateExpectedTimes();
    }

    // 计算并更新预计时间
    function updateExpectedTimes() {
        const totalCombinations = Math.pow(10, state.digits);

        // 人类时间计算
        const humanTotalSeconds = totalCombinations * 3;
        let humanTimeStr = '';
        if (humanTotalSeconds < 3600) {
            humanTimeStr = `${Math.round(humanTotalSeconds / 60)} 分钟`;
        } else if (humanTotalSeconds < 86400) {
            humanTimeStr = `${(humanTotalSeconds / 3600).toFixed(1)} 小时`;
        } else {
            humanTimeStr = `${(humanTotalSeconds / 86400).toFixed(1)} 天 (不吃不睡)`;
        }

        // 电脑时间计算
        const computerTotalSeconds = totalCombinations / COMPUTER_SPEED;
        let computerTimeStr = '';
        if (computerTotalSeconds < 1) {
            computerTimeStr = `${(computerTotalSeconds * 1000).toFixed(0)} 毫秒`;
        } else {
            computerTimeStr = `${computerTotalSeconds.toFixed(2)} 秒`;
        }

        humanTimeEl.textContent = humanTimeStr;
        computerTimeEl.textContent = computerTimeStr;

        comparisonText.innerHTML = `在 <strong>${state.digits}</strong> 位密码下，共有 <strong>${totalCombinations.toLocaleString()}</strong> 种组合。<br>` +
            `电脑仅需约 <strong class="computer-value">${computerTimeStr}</strong> 即可全部试完；<br>` +
