    limitSwitch.addEventListener('change', (e) => {
        state.limitAttempts = e.target.checked;
        resetSimulation();
    });

    // 重置模拟
    function resetSimulation() {
        state.isRunning = false;
        cancelAnimationFrame(state.animationFrameId);
        state.humanAttempts = 0;
        state.computerAttempts = 0;

        humanFill.style.width = '0%';
        computerFill.style.width = '0%';
        humanAttemptsEl.textContent = '0';
        computerAttemptsEl.textContent = '0';
        humanWarning.style.display = 'none';
        lockoutOverlay.classList.remove('active');

        const slots = document.querySelectorAll('.pin-slot');
        slots.forEach(slot => {
