    // 动画循环
    function animate() {
        if (!state.isRunning) return;

        const totalCombinations = Math.pow(10, state.digits);

        // 为了在课堂上有良好的视觉演示效果：
        // 1. 电脑破译：在 2-4 秒内视觉上完成 100% 的进度，但数值显示真实的破译进度。
        // 2. 人类破译：如果开启了限制，在第 5 次尝试时立刻触发锁定。
        //             如果未开启限制，人类进度条以极慢的速度移动，并触发疲劳警告。

        // 电脑进度更新 (模拟视觉动画，实际计算速度极快)
        if (state.computerAttempts < totalCombinations) {
