            btnStart.textContent = '破译结束';
            btnStart.style.backgroundColor = '#7f8c8d';
            // 最终显示成功破译的密码（随机模拟一个）
            slots.forEach(slot => {
                slot.textContent = Math.floor(Math.random() * 10);
                slot.classList.add('active');
            });
            return;
        }

        state.animationFrameId = requestAnimationFrame(animate);
    }

    // 密码槽闪烁效果（模拟输入）
    function triggerSlotFlash() {
        const slots = document.querySelectorAll('.pin-slot');
        if (slots.length > 0) {
            const randomSlot = slots[Math.floor(Math.random() * slots.length)];
            randomSlot.classList.add('active');
            setTimeout(() => randomSlot.classList.remove('active'), 150);
        }
    }

    // 初始化
    initPinSlots();
</script>

