        if (lossMin > lossMax) {
            if (this === slideLossMin) {
                slideLossMax.value = lossMin;
                lossMax = lossMin;
            } else {
                slideLossMin.value = lossMax;
                lossMin = lossMax;
            }
        }

        // 计算剩余人数区间
        const remainMin = TOTAL_SOLDIERS - lossMax;
        const remainMax = TOTAL_SOLDIERS - lossMin;

        // 1. 更新文本标签
        lblLossMin.textContent = lossMin;
        lblLossMax.textContent = lossMax;
