        tickRemainMax.setAttribute('x1', xRemainMax);
        tickRemainMax.setAttribute('x2', xRemainMax);
        txtRemainMax.setAttribute('x', xRemainMax);
        txtRemainMax.textContent = `${remainMax}人`;

        // 搜索范围描述文字居中
        txtRangeDesc.setAttribute('x', xRemainMin + remainWidth / 2);

