    <title>控制结构调试器：并列 vs 嵌套</title>
    <style>
        :root {
            --primary-color: #4c97ff;
            --control-color: #ffab19;
            --control-dark: #cf8b10;
            --looks-color: #9966ff;
            --looks-dark: #7a4ecc;
            --bg-color: #f0f4f8;
            --panel-bg: #ffffff;
            --text-color: #2c3e50;
            --border-color: #d0d7de;
            --success-color: #2ecc71;
            --fail-color: #e74c3c;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: "Helvetica Neue", Helvetica, Arial, "Microsoft YaHei", sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 10px;
        }

        /* 4:3 比例自适应容器 */
        .app-container {
            width: 100%;
            max-width: 1024px;
            aspect-ratio: 4 / 3;
            background: var(--panel-bg);
            border-radius: 16px;
            box-shadow: 0 8px 24px rgba(0,0,0,0.08);
            display: flex;
            flex-direction: column;
            overflow: hidden;
            border: 1px solid var(--border-color);
        }

        /* 头部标题栏 */
        .header {
            background: linear-gradient(135deg, #2a6ecf, #4c97ff);
            color: white;
            padding: 15px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .header h1 {
            font-size: 20px;
            font-weight: bold;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .header .badge {
            background: rgba(255, 255, 255, 0.2);
            padding: 4px 10px;
            border-radius: 20px;
            font-size: 12px;
        }

        /* 控制面板 */
        .control-panel {
            background: #f8f9fa;
            border-bottom: 1px solid var(--border-color);
            padding: 12px 20px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 15px;
        }

        .selector-group {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .selector-label {
            font-size: 14px;
            font-weight: bold;
            color: #555;
        }

        .num-btn {
            background: white;
            border: 2px solid var(--border-color);
            border-radius: 8px;
            padding: 6px 14px;
            font-size: 14px;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.2s;
        }

        .num-btn:hover {
            border-color: var(--primary-color);
            color: var(--primary-color);
        }

        .num-btn.active {
            background: var(--primary-color);
            border-color: var(--primary-color);
            color: white;
        }

        .custom-input-wrapper {
            display: flex;
            align-items: center;
            gap: 5px;
            border-left: 2px solid var(--border-color);
            padding-left: 10px;
        }

        .custom-input {
            width: 60px;
            padding: 5px;
            border: 2px solid var(--border-color);
            border-radius: 6px;
            text-align: center;
            font-weight: bold;
            font-size: 14px;
        }

        .custom-input:focus {
            outline: none;
            border-color: var(--primary-color);
        }

        .action-group {
            display: flex;
            gap: 8px;
        }

        .btn {
            border: none;
            border-radius: 8px;
            padding: 8px 16px;
            font-size: 14px;
            font-weight: bold;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 6px;
            transition: all 0.2s;
        }

        .btn-primary {
            background: #2ecc71;
            color: white;
        }

        .btn-primary:hover {
            background: #27ae60;
        }

        .btn-secondary {
            background: #9b59b6;
            color: white;
        }

        .btn-secondary:hover {
            background: #8e44ad;
        }

        .btn-danger {
            background: #e74c3c;
            color: white;
        }

        .btn-danger:hover {
            background: #c0392b;
        }

        .btn:disabled {
            background: #bdc3c7;
            cursor: not-allowed;
        }

        /* 主工作区 */
        .workspace {
            flex: 1;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 15px;
            padding: 15px;
            background: #f5f6f7;
            overflow: hidden;
        }

        .column {
            display: flex;
            flex-direction: column;
            background: var(--panel-bg);
            border-radius: 12px;
            border: 1px solid var(--border-color);
            padding: 12px;
            overflow: hidden;
