            font-weight: bold;
            margin-bottom: 10px;
            padding-bottom: 6px;
            border-bottom: 2px solid #eee;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .column-title .tag {
            font-size: 11px;
            padding: 2px 8px;
            border-radius: 10px;
            color: white;
