            border-radius: 8px;
            padding: 10px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        /* Scratch 积木样式 */
        .scratch-block {
            font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
            font-size: 13px;
            font-weight: bold;
            user-select: none;
            transition: all 0.2s;
        }

        .control-block {
            background: var(--control-color);
            border: 1px solid var(--control-dark);
            border-radius: 4px;
            color: white;
            display: flex;
            flex-direction: column;
            width: 100%;
            box-sizing: border-box;
        }

        .control-block.active-check {
            box-shadow: 0 0 0 3px #39ff14;
            transform: scale(1.01);
        }

        .header-line {
            padding: 6px 10px;
            display: flex;
            align-items: center;
            flex-wrap: wrap;
            gap: 6px;
        }

        .cond-tag {
            background: #e1930f;
            border: 1px solid #b87503;
            border-radius: 12px;
            padding: 1px 8px;
            font-size: 11px;
            color: #fff;
            display: inline-flex;
            align-items: center;
            gap: 3px;
        }

        .scratch-body {
            border-left: 15px solid var(--control-color);
            padding: 4px 0 4px 10px;
            background: rgba(255,255,255,0.1);
            display: flex;
            flex-direction: column;
            gap: 4px;
            min-height: 20px;
        }

        .footer-line {
            height: 6px;
            background: var(--control-color);
            border-radius: 0 0 4px 4px;
        }

        .looks-block {
            background: var(--looks-color);
            border: 1px solid var(--looks-dark);
            border-radius: 4px;
            color: white;
            padding: 5px 10px;
            width: fit-content;
        }

        .looks-block.active-run {
            animation: pulse-purple 0.6s infinite alternate;
        }

        @keyframes pulse-purple {
            0% { box-shadow: 0 0 2px #9966ff; }
            100% { box-shadow: 0 0 12px #9966ff; transform: scale(1.03); }
        }

        .val-tag {
            background: #fff;
            color: #575757;
            border-radius: 4px;
            padding: 1px 5px;
            font-size: 11px;
        }

        /* 状态指示灯 */
        .status-indicator {
            margin-left: auto;
            font-size: 12px;
            padding: 1px 6px;
            border-radius: 8px;
            background: rgba(0,0,0,0.2);
            display: none;
        }

        .status-indicator.pass {
            display: inline-block;
            background-color: var(--success-color);
            color: white;
            animation: pop 0.3s ease;
        }

        .status-indicator.fail {
            display: inline-block;
            background-color: var(--fail-color);
            color: white;
            animation: shake 0.3s ease;
        }

        @keyframes pop {
            0% { transform: scale(0.5); }
            100% { transform: scale(1); }
        }

        @keyframes shake {
            0%, 100% { transform: translateX(0); }
            25% { transform: translateX(-3px); }
            75% { transform: translateX(3px); }
        }

        /* 舞台区 */
        .stage {
            height: 130px;
            background: #ffffff;
            border: 2px solid var(--border-color);
            border-radius: 8px;
            margin-top: 10px;
            position: relative;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            padding: 8px;
            transition: all 0.3s;
        }

        .stage.flash {
            border-color: var(--looks-color);
            box-shadow: 0 0 10px rgba(153, 102, 255, 0.5);
        }

        .stage-title {
            font-size: 11px;
            color: #888;
            font-weight: bold;
            border-bottom: 1px solid #f0f0f0;
            padding-bottom: 2px;
        }

        .stage-canvas {
            flex: 1;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* 舞台角色 */
        .sprite-container {
            position: absolute;
            bottom: 5px;
            left: 15px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .sprite-svg {
            width: 45px;
            height: 45px;
        }

        .speech-bubble {
            background: white;
            border: 2px solid #575757;
            border-radius: 10px;
            padding: 4px 10px;
            font-size: 12px;
            font-weight: bold;
            color: #333;
            box-shadow: 2px 2px 5px rgba(0,0,0,0.1);
            position: relative;
            display: none;
            max-width: 120px;
            word-break: break-all;
        }

        .speech-bubble::after {
            content: '';
