<script>
    // 常量与状态
    const START_YEAR = 2000;
    const END_YEAR = 2100;
    const TOTAL_YEARS = END_YEAR - START_YEAR + 1;

    let currentStrategy = 1; // 1 或 4
    let isRunning = false;
    let timer = null;
    let currentYearPointer = START_YEAR;
    let loopCount = 0;
    let leapCount = 0;
    let checkedStates = {}; // 记录每个年份的检查状态: 'none', 'checking', 'leap', 'not-leap', 'skipped'

    // DOM 元素
    const yearGrid = document.getElementById('year-grid');
    const btnStart = document.getElementById('btn-start');
    const btnReset = document.getElementById('btn-reset');
    const stratStep1 = document.getElementById('strat-step1');
    const stratStep4 = document.getElementById('strat-step4');
    const labelStep1 = document.getElementById('label-step1');
    const labelStep4 = document.getElementById('label-step4');
    const statLoops = document.getElementById('stat-loops');
    const statLeaps = document.getElementById('stat-leaps');
    const pruneBanner = document.getElementById('prune-banner');
    const speedSlider = document.getElementById('speed-slider');

    // 初始化网格
    function initGrid() {
        yearGrid.innerHTML = '';
        checkedStates = {};
        for (let y = START_YEAR; y <= END_YEAR; y++) {
            const cell = document.createElement('div');
            cell.className = 'year-cell';
            cell.id = `year-${y}`;
            cell.textContent = y;
            yearGrid.appendChild(cell);

            // 初始状态
            if (currentStrategy === 4 && (y - START_YEAR) % 4 !== 0) {
                checkedStates[y] = 'skipped';
                cell.classList.add('skipped');
            } else {
                checkedStates[y] = 'none';
            }
        }
    }

    // 判断是否为闰年 (标准算法)
    function isLeapYear(year) {
        // 能被4整除但不能被100整除，或者能被400整除
        return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
    }

    // 更新单选按钮视觉效果
    function updateStrategyUI(strategy) {
        currentStrategy = strategy;
        if (strategy === 1) {
            labelStep1.classList.add('active');
            labelStep4.classList.remove('active');
            stratStep1.checked = true;
            pruneBanner.classList.remove('show');
        } else {
            labelStep4.classList.add('active');
            labelStep1.classList.remove('active');
            stratStep4.checked = true;
            pruneBanner.classList.add('show');
        }
        resetSimulation();
    }

    // 重置模拟
    function resetSimulation() {
        stopSimulation();
        currentYearPointer = START_YEAR;
        loopCount = 0;
        leapCount = 0;
        statLoops.textContent = '0';
        statLeaps.textContent = '0';
        btnStart.disabled = false;
        btnStart.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polygon points="5 3 19 12 5 21 5 3"/></svg> 开始检索`;
        initGrid();
    }

    // 停止模拟
    function stopSimulation() {
        isRunning = false;
        if (timer) {
            clearTimeout(timer);
            timer = null;
        }
    }

    // 单步执行
    function stepForward() {
        if (!isRunning) return;

        // 如果指针超出范围，结束
        if (currentYearPointer > END_YEAR) {
            stopSimulation();
            btnStart.disabled = true;
            btnStart.innerHTML = `检索完成`;
            return;
        }

        // 清除上一个正在检查的样式
        const prevChecking = document.querySelector('.year-cell.checking');
        if (prevChecking) {
            prevChecking.classList.remove('checking');
        }

        // 获取当前单元格
        const cell = document.getElementById(`year-${currentYearPointer}`);
        if (cell) {
            cell.classList.add('checking');

            // 增加循环计数
            loopCount++;
            statLoops.textContent = loopCount;

            // 延迟判定结果，让学生看清“正在检查”的过程
            const delay = Math.max(20, 320 - speedSlider.value);

            setTimeout(() => {
                if (!isRunning) return;

                cell.classList.remove('checking');
                if (isLeapYear(currentYearPointer)) {
                    cell.classList.add('leap');
                    leapCount++;
                    statLeaps.textContent = leapCount;
                } else {
                    cell.classList.add('not-leap');
                }

                // 移动指针到下一个需要检查的年份
                currentYearPointer += currentStrategy;

                // 递归下一步
                timer = setTimeout(stepForward, delay / 2);
            }, delay / 2);
        } else {
            // 如果因为某种原因没找到单元格，直接跳过
            currentYearPointer += currentStrategy;
            stepForward();
        }
    }

    // 开始/暂停
    function togglePlay() {
        if (isRunning) {
            stopSimulation();
            btnStart.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polygon points="5 3 19 12 5 21 5 3"/></svg> 继续检索`;
        } else {
            isRunning = true;
            btnStart.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg> 暂停`;
            stepForward();
        }
    }

    // 事件监听
    labelStep1.addEventListener('click', () => {
        if (!isRunning) updateStrategyUI(1);
    });

    labelStep4.addEventListener('click', () => {
        if (!isRunning) updateStrategyUI(4);
    });

    btnStart.addEventListener('click', togglePlay);
    btnReset.addEventListener('click', resetSimulation);

    // 初始化
    updateStrategyUI(1);
</script>

