    const START_X = 50;

    // 更新视图函数
    function updateVisualization(deadCount) {
        const remainingCount = TOTAL_SOLDIERS - deadCount;

        // 计算比例宽度
        const remainingWidth = (remainingCount / TOTAL_SOLDIERS) * SVG_WIDTH_UNITS;
        const deadWidth = (deadCount / TOTAL_SOLDIERS) * SVG_WIDTH_UNITS;
        const deadX = START_X + remainingWidth;

        // 更新SVG元素属性
        rectRemaining.setAttribute('width', remainingWidth);
        rectDead.setAttribute('x', deadX);
        rectDead.setAttribute('width', deadWidth);

        // 更新标注文字位置与内容
