        textDeadVal.setAttribute('x', deadX + (deadWidth / 2));

        textRemainVal.textContent = `剩余: ${remainingCount}人`;
        // 剩余文字定位在绿色区域中点
        textRemainVal.setAttribute('x', START_X + (remainingWidth / 2));

        // 更新公式
        formulaDead.textContent = deadCount;
        formulaRemain.textContent = remainingCount;

        // 更新控制台标签
        sliderLabel.textContent = `设定战死人数: ${deadCount} 人`;

        // 更新按钮高亮状态
        if (deadCount === 400) {
            btnMin.classList.add('active');
            btnMax.classList.remove('active');
        } else if (deadCount === 500) {
            btnMax.classList.add('active');
            btnMin.classList.remove('active');
        } else {
            btnMin.classList.remove('active');
            btnMax.classList.remove('active');
        }
    }

    // 滑块事件监听
    slider.addEventListener('input', (e) => {
        const val = parseInt(e.target.value, 10);
        updateVisualization(val);
    });

    // 按钮事件监听
    btnMin.addEventListener('click', () => {
        slider.value = 400;
        updateVisualization(400);
    });

    btnMax.addEventListener('click', () => {
        slider.value = 500;
        updateVisualization(500);
    });

    // 初始化
    updateVisualization(400);
