        const formulaCard = document.getElementById('formula-card');
        const successGlow = document.getElementById('success-glow');

        const weightColors = {
            1: { body: '#3b82f6', loop: '#1d4ed8' },
            2: { body: '#22c55e', loop: '#15803d' },
            3: { body: '#a855f7', loop: '#7e22ce' }
        };

        let currentAngle = -15;
        let targetAngle = -15;

        // Mathematical model to update the SVG balance scale based on angle
        function setScaleAngle(degrees) {
            const rad = degrees * Math.PI / 180;
            const L_cx = 400 - 200 * Math.cos(rad);
            const L_cy = 200 - 200 * Math.sin(rad);
            const R_cx = 400 + 200 * Math.cos(rad);
            const R_cy = 200 + 200 * Math.sin(rad);

            // Update beam
            document.getElementById('beam').setAttribute('x1', L_cx);
            document.getElementById('beam').setAttribute('y1', L_cy);
            document.getElementById('beam').setAttribute('x2', R_cx);
            document.getElementById('beam').setAttribute('y2', R_cy);

            // Update pivots
            document.getElementById('pivot-L').setAttribute('cx', L_cx);
            document.getElementById('pivot-L').setAttribute('cy', L_cy);
            document.getElementById('pivot-R').setAttribute('cx', R_cx);
            document.getElementById('pivot-R').setAttribute('cy', R_cy);

            // Update needle (perpendicular to the beam)
            const needleLength = 50;
            const N_x = 400 - needleLength * Math.sin(rad);
            const N_y = 200 - needleLength * Math.cos(rad);
            document.getElementById('needle').setAttribute('x2', N_x);
            document.getElementById('needle').setAttribute('y2', N_y);

            // Update pans (translate relative to their balanced positions)
            document.getElementById('left-pan-group').setAttribute('transform', `translate(${L_cx - 200}, ${L_cy - 200})`);
            document.getElementById('right-pan-group').setAttribute('transform', `translate(${R_cx - 600}, ${R_cy - 200})`);
        }

        // Smooth animation loop
        function animate() {
            if (Math.abs(currentAngle - targetAngle) > 0.05) {
                currentAngle += (targetAngle - currentAngle) * 0.1;
                setScaleAngle(currentAngle);
            }
            requestAnimationFrame(animate);
        }

        function selectWeight(num) {
            // Update placed weight visuals
            placedWeightBody.setAttribute('fill', weightColors[num].body);
            placedWeightLoop.setAttribute('fill', weightColors[num].loop);
            placedWeightText.textContent = num;
            placedWeight.setAttribute('opacity', '1');
            placeholder.setAttribute('opacity', '0');

            // Update scale target angle and feedback
            if (num === 1) {
                targetAngle = -7;
                feedback.textContent = "不平衡哦！x % 3 等于 1 表示余数是 1。再试一试！";
                feedback.className = "feedback-box error";
                formulaCard.classList.remove('show');
                successGlow.classList.remove('glow-active');
            } else if (num === 2) {
                targetAngle = 0;
                feedback.textContent = "太棒了！天平平衡了！";
                feedback.className = "feedback-box success";
                formulaCard.classList.add('show');
                successGlow.classList.add('glow-active');
            } else if (num === 3) {
                targetAngle = 10;
                feedback.textContent = "不平衡哦！除以 3 的余数不可能等于 3 呀（余数必须小于除数）！";
                feedback.className = "feedback-box error";
                formulaCard.classList.remove('show');
                successGlow.classList.remove('glow-active');
            }
        }

        function resetScale() {
            targetAngle = -15;
            placedWeight.setAttribute('opacity', '0');
            placeholder.setAttribute('opacity', '1');
            feedback.textContent = "请选择一个砝码放入右盘，使天平平衡。";
            feedback.className = "feedback-box";
            formulaCard.classList.remove('show');
            successGlow.classList.remove('glow-active');
        }

        // Event Listeners
        btnW1.addEventListener('click', () => selectWeight(1));
        btnW2.addEventListener('click', () => selectWeight(2));
        btnW3.addEventListener('click', () => selectWeight(3));
        placedWeight.addEventListener('click', resetScale);

        // Initialize scale position and start animation
        setScaleAngle(currentAngle);
        animate();
    });
</script>

