            const rings = document.querySelectorAll('.ring');
            const chainStage = document.getElementById('chainStage');

            // 状态变量
            let selectedSymbolType = null;
            let slotStates = [null, null]; // 存储两个插槽的状态: 'and', 'or' 或 null
            let sparkleInterval = null;

            // --- 交互逻辑一：点击选择与放置 (对触屏/白板极友好) ---

            symbols.forEach(symbol => {
