                    // 如果已经选中，则取消选中
                    if (symbol.classList.contains('selected')) {
                        symbol.classList.remove('selected');
                        selectedSymbolType = null;
                    } else {
                        // 清除其他选中
                        symbols.forEach(s => s.classList.remove('selected'));
                        symbol.classList.add('selected');
                        selectedSymbolType = symbol.getAttribute('data-type');
