                    const index = parseInt(slot.getAttribute('data-index'));

                    if (selectedSymbolType) {
                        // 放置选中的符号
                        placeSymbol(index, selectedSymbolType);
                        // 清除符号选中状态
                        symbols.forEach(s => s.classList.remove('selected'));
                        selectedSymbolType = null;
                    } else if (slotStates[index]) {
                        // 如果插槽有东西且没选择新符号，点击则清空
                        clearSlot(index);
