            // --- 核心业务逻辑 ---

            // 放置符号
            function placeSymbol(slotIndex, type) {
                slotStates[slotIndex] = type;
                const slot = document.getElementById(`slot${slotIndex}`);

                // 渲染插槽内部
                const label = type === 'and' ? '且 (and)' : '或 (or)';
                slot.innerHTML = `
                    <div class="placed-symbol" data-type="${type}">
                        <span style="font-size: 15px;">${label}</span>
                    </div>
                `;

                checkLogic();
            }

            // 清空插槽
            function clearSlot(slotIndex) {
                slotStates[slotIndex] = null;
                const slot = document.getElementById(`slot${slotIndex}`);
                slot.innerHTML = `<div class="slot-placeholder">放入<br>符号</div>`;

                checkLogic();
            }

            // 逻辑判定
            function checkLogic() {
                // 停止之前的特效
                stopSparkles();
                chainLine.classList.remove('active');
                rings.forEach(r => r.classList.remove('active'));

                const [s1, s2] = slotStates;

                if (s1 === null || s2 === null) {
                    // 未填满
                    feedback.className = 'feedback-box';
                    feedback.textContent = '锁链还未闭合，请继续连接剩下的空缺。';
                } else if (s1 === 'and' && s2 === 'and') {
                    // 成功：全部为“且”
                    feedback.className = 'feedback-box success';
                    feedback.textContent = '🎉 太棒了！“且”将三个条件完美绑定！表示它们必须【同时成立】。';

                    // 激活金色特效
                    chainLine.classList.add('active');
                    rings.forEach(r => r.classList.add('active'));
                    startSparkles();
                } else {
                    // 错误：包含“或”
                    feedback.className = 'feedback-box warning';
                    if (s1 === 'or' && s2 === 'or') {
                        feedback.textContent = '⚠️ 提示：“或”表示只要满足其中任意一个就可以。但我们需要三个条件【同时成立】哦！';
                    } else {
                        feedback.textContent = '⚠️ 提示：锁链中混入了“或”，这会导致部分条件变成“可选”，无法保证三个条件【同时成立】。';
                    }
                }
            }

            // 重置
            btnReset.addEventListener('click', () => {
                slotStates = [null, null];
                slots.forEach((slot, index) => {
                    if (index === 0) {
                        slot.innerHTML = `
                            <div class="slot-placeholder">放入<br>符号</div>
                            <div class="guide-tip">点击或拖入</div>
                        `;
                    } else {
                        slot.innerHTML = `<div class="slot-placeholder">放入<br>符号</div>`;
                    }
                });
                symbols.forEach(s => s.classList.remove('selected'));
                selectedSymbolType = null;
                checkLogic();
                feedback.className = 'feedback-box';
                feedback.textContent = '请选择合适的逻辑符号，将三个独立的数学条件绑定在一起。';
            });

            // --- 视觉特效：金色粒子 ---

            function startSparkles() {
