                clearInterval(sparkleInterval);
                const sparkles = document.querySelectorAll('.sparkle');
                sparkles.forEach(s => s.remove());
            }

            function createSparkle() {
                const sparkle = document.createElement('div');
                sparkle.classList.add('sparkle');

                // 随机大小
