                sparkle.style.left = `${left}px`;
                sparkle.style.top = `${top}px`;

                chainStage.appendChild(sparkle);

                // 动画结束后移除
                setTimeout(() => {
                    sparkle.remove();
                }, 1000);
            }
        });
