    <script>
        // 获取 DOM 元素
        const playBtn = document.getElementById('btn-play');
        const stepBtn = document.getElementById('btn-step');
        const resetBtn = document.getElementById('btn-reset');
        const speedSlider = document.getElementById('speed-slider');

        const trackActive = document.getElementById('loop-track-active');
        const dataDot = document.getElementById('data-dot');
        const dataGlow = document.getElementById('data-glow');
        const glowShadow = document.getElementById('glow-shadow');

        const nodeGet = document.getElementById('node-get');
        const nodeJudge = document.getElementById('node-judge');

        const monLoop = document.getElementById('mon-loop');
        const monNum = document.getElementById('mon-num');
        const monResult = document.getElementById('mon-result');
        const stepDesc = document.getElementById('step-desc');

        // 动画路径定义
        const pathEl = document.getElementById('loop-track-active');
