        // 模拟数据
        const numbersToProcess = [12, 7, 15, 8];
        let currentNumberIndex = 0;
        let loopCount = 0;

        // 动画状态控制
        let isPlaying = false;
        let progress = 0; // 0 to 1
        let animationFrameId = null;
        let currentStepState = 'idle'; // idle, entering, getting, judging, looping

        // 速度映射
        const speedMap = {
            1: 0.002, // 慢
            2: 0.005, // 中
            3: 0.01   // 快
        };
        let speed = speedMap[2];

        // 初始化显示
        function init() {
            progress = 0;
            currentNumberIndex = 0;
            loopCount = 0;
            isPlaying = false;
            currentStepState = 'idle';

            // 隐藏光点
            dataDot.style.display = 'none';
            dataGlow.style.display = 'none';
            glowShadow.style.display = 'none';

            // 重置高亮
            nodeGet.classList.remove('active');
            nodeJudge.classList.remove('active');
            trackActive.setAttribute('stroke', '#0284c7');
            trackActive.setAttribute('opacity', '0.4');

            // 重置监视器
            monLoop.textContent = '-';
            monNum.textContent = '-';
            monResult.textContent = '-';
            stepDesc.innerHTML = '点击“自动运行”或“单步执行”，观察数据流动的轨迹。';

            playBtn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg><span>自动运行</span>`;
        }

        // 更新光点位置
        function updateDotPosition(p) {
            const point = pathEl.getPointAtLength(p * pathLength);

            dataDot.setAttribute('cx', point.x);
            dataDot.setAttribute('cy', point.y);
            dataGlow.setAttribute('cx', point.x);
            dataGlow.setAttribute('cy', point.y);
            glowShadow.setAttribute('cx', point.x);
            glowShadow.setAttribute('cy', point.y);

            dataDot.style.display = 'block';
            dataGlow.style.display = 'block';
            glowShadow.style.display = 'block';
        }

        // 状态机：根据当前进度更新UI和文本
        function updateState(p) {
            // 将 0-1 的进度划分为不同阶段
            // 路径总长中各节点的大致位置：
            // 0.0 ~ 0.15 : 从入口到“取数框”上方
            // 0.15 ~ 0.30 : 在“取数框”内
            // 0.30 ~ 0.50 : 从“取数框”到“判断框”
            // 0.50 ~ 0.65 : 在“判断框”内
            // 0.65 ~ 1.0  : 沿着大肚子轨道返回

            const currentNum = numbersToProcess[currentNumberIndex];

            if (p < 0.15) {
                if (currentStepState !== 'entering') {
                    currentStepState = 'entering';
                    nodeGet.classList.remove('active');
                    nodeJudge.classList.remove('active');
                    if (loopCount === 0) {
                        stepDesc.innerHTML = '数据准备进入循环结构...';
                    } else {
                        stepDesc.innerHTML = '准备开始下一轮循环...';
                    }
                }
            } 
            else if (p >= 0.15 && p < 0.35) {
                if (currentStepState !== 'getting') {
                    currentStepState = 'getting';
                    nodeGet.classList.add('active');
                    nodeJudge.classList.remove('active');

                    if (p > 0.15) {
                        loopCount++;
