    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const workspace = document.getElementById('workspace');
            const svg = document.getElementById('connector-svg');
            const pathSet = document.getElementById('path-set');
            const pathChange = document.getElementById('path-change');

            const flowNodeSet = document.getElementById('flow-node-set');
            const flowNodeChange = document.getElementById('flow-node-change');
            const blockSet = document.getElementById('block-set');
            const blockChange = document.getElementById('block-change');

