            function updateSinglePath(flowNode, blockNode, pathElement, svgRect) {
                const r1 = flowNode.getBoundingClientRect();
                const r2 = blockNode.getBoundingClientRect();

                // 起点：流程图节点的右侧中心
                const x1 = r1.right - svgRect.left;
                const y1 = r1.top + r1.height / 2 - svgRect.top;

                // 终点：积木块的左侧中心
                const x2 = r2.left - svgRect.left;
                const y2 = r2.top + r2.height / 2 - svgRect.top;

                // 绘制贝塞尔曲线
                const controlOffset = Math.abs(x2 - x1) * 0.5;
                pathElement.setAttribute('d', `M ${x1} ${y1} C ${x1 + controlOffset} ${y1}, ${x2 - controlOffset} ${y2}, ${x2} ${y2}`);
            }

            // 激活/取消激活连接线和高亮
            function activateConnection(type) {
                // 重置所有
                deactivateAll();

                if (type === 'set') {
                    flowNodeSet.classList.add('active');
                    blockSet.classList.add('active');
                    pathSet.classList.add('active');
                    showTips("“i = 1000” 对应 变量初始化积木 设为 1000");
                } else if (type === 'change') {
                    flowNodeChange.classList.add('active');
                    blockChange.classList.add('active');
                    pathChange.classList.add('active');
                    showTips("“i = i + 1” 对应 变量自增积木 增加 1");
                }
            }

            function deactivateAll() {
                flowNodeSet.classList.remove('active');
                blockSet.classList.remove('active');
                pathSet.classList.remove('active');

                flowNodeChange.classList.remove('active');
                blockChange.classList.remove('active');
                pathChange.classList.remove('active');

                tips.classList.remove('show');
            }

            function showTips(text) {
                tips.textContent = text;
                tips.classList.add('show');
            }

            // 绑定交互事件
            flowNodeSet.addEventListener('mouseenter', () => activateConnection('set'));
            blockSet.addEventListener('mouseenter', () => activateConnection('set'));
