<script>
    // 获取 DOM 元素
    const morphingShape = document.getElementById('morphing-shape');
    const morphingText = document.getElementById('morphing-text');
    const btnPair = document.getElementById('btn-pair');
    const btnReset = document.getElementById('btn-reset');
    const infoCard = document.getElementById('info-card');
    const statusLed = document.getElementById('status-led');
    const statusText = document.getElementById('status-text');

    // 动画状态变量
    let isAnimating = false;
    let isPaired = false;
    const duration = 1200; // 动画持续时间 (毫秒)

    // 关键帧顶点数据
    // 初始状态：菱形 (用 6 个点表示，其中上下顶点重复)
    const startPoints = [
        [200, 150], // 顶点1 (上左)
        [200, 150], // 顶点2 (上右)
        [280, 200], // 顶点3 (右)
        [200, 250], // 顶点4 (下右)
        [200, 250], // 顶点5 (下左)
        [120, 200]  // 顶点6 (左)
    ];

    // 目标状态：六角形 (完美契合 Scratch 积木的插槽)
    const endPoints = [
        [525, 175], // 顶点1 (上左)
        [585, 175], // 顶点2 (上右)
        [595, 182], // 顶点3 (右)
        [585, 189], // 顶点4 (下右)
        [525, 189], // 顶点5 (下左)
        [515, 182]  // 顶点6 (左)
    ];

    // 文本属性过渡数据
    const startTextAttr = { x: 200, y: 206, size: 16, r: 0, g: 96, b: 100 };
    const endTextAttr = { x: 555, y: 186, size: 10, r: 255, g: 255, b: 255 };

    // 颜色过渡数据
    const startFill = { r: 224, g: 247, b: 250 }; // #E0F7FA (浅蓝)
    const endFill = { r: 92, g: 184, b: 92 };     // #5CB85C (Scratch 条件绿)

    const startStroke = { r: 0, g: 172, b: 193 };  // #00ACC1
    const endStroke = { r: 255, g: 255, b: 255 };  // 白色

    // 缓动函数：InOutQuad
    function easeInOutQuad(t) {
        return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    }

    // 线性插值
    function lerp(start, end, amt) {
        return (1 - amt) * start + amt * end;
    }

    // 执行动画
    function runAnimation(reverse = false) {
        if (isAnimating) return;
        isAnimating = true;

        // 移除呼吸灯效果
        morphingShape.classList.remove('pulse-active');

        const startTime = performance.now();

        function update(currentTime) {
            const elapsed = currentTime - startTime;
            let progress = Math.min(elapsed / duration, 1);

            // 如果是反向动画 (重置)
            const t = reverse ? 1 - progress : progress;
            const ease = easeInOutQuad(t);

            // 1. 插值计算多边形顶点
            const currentPoints = startPoints.map((startPt, i) => {
                const endPt = endPoints[i];
                const x = lerp(startPt[0], endPt[0], ease);
                const y = lerp(startPt[1], endPt[1], ease);
                return `${x.toFixed(1)},${y.toFixed(1)}`;
            }).join(' ');

            morphingShape.setAttribute('points', currentPoints);

            // 2. 插值计算文本位置与大小
            const textX = lerp(startTextAttr.x, endTextAttr.x, ease);
            const textY = lerp(startTextAttr.y, endTextAttr.y, ease);
            const textSize = lerp(startTextAttr.size, endTextAttr.size, ease);

            morphingText.setAttribute('x', textX);
            morphingText.setAttribute('y', textY);
            morphingText.style.fontSize = `${textSize}px`;

            // 3. 插值计算文本颜色
            const tr = Math.round(lerp(startTextAttr.r, endTextAttr.r, ease));
            const tg = Math.round(lerp(startTextAttr.g, endTextAttr.g, ease));
            const tb = Math.round(lerp(startTextAttr.b, endTextAttr.b, ease));
            morphingText.setAttribute('fill', `rgb(${tr},${tg},${tb})`);

            // 4. 插值计算填充颜色与边框颜色
            const fr = Math.round(lerp(startFill.r, endFill.r, ease));
            const fg = Math.round(lerp(startFill.g, endFill.g, ease));
            const fb = Math.round(lerp(startFill.b, endFill.b, ease));
            morphingShape.setAttribute('fill', `rgb(${fr},${fg},${fb})`);

            const sr = Math.round(lerp(startStroke.r, endStroke.r, ease));
            const sg = Math.round(lerp(startStroke.g, endStroke.g, ease));
            const sb = Math.round(lerp(startStroke.b, endStroke.b, ease));
            morphingShape.setAttribute('stroke', `rgb(${sr},${sg},${sb})`);

            if (progress < 1) {
                requestAnimationFrame(update);
            } else {
                isAnimating = false;
                isPaired = !reverse;

                // 动画结束后的状态更新
                if (isPaired) {
                    // 成功配对状态
                    statusLed.setAttribute('fill', '#00E676');
                    statusLed.setAttribute('filter', 'url(#green-glow)');
                    statusText.textContent = '已配对';
                    statusText.setAttribute('fill', '#2E7D32');
                    infoCard.classList.add('show');
                    btnPair.disabled = true;
                    btnReset.disabled = false;
                } else {
                    // 重置回初始状态
                    statusLed.setAttribute('fill', '#90A4AE');
                    statusLed.removeAttribute('filter');
                    statusText.textContent = '未配对';
                    statusText.setAttribute('fill', '#546E7A');
                    infoCard.classList.remove('show');
                    morphingShape.classList.add('pulse-active');
                    btnPair.disabled = false;
                    btnReset.disabled = true;
                }
            }
        }

        requestAnimationFrame(update);
    }

    // 绑定事件监听器
    btnPair.addEventListener('click', () => {
        if (!isPaired) runAnimation(false);
    });

    btnReset.addEventListener('click', () => {
        if (isPaired) runAnimation(true);
    });

    // 点击图形本身也可以触发配对
    morphingShape.addEventListener('click', () => {
        if (!isPaired && !isAnimating) {
            runAnimation(false);
        }
    });
