            <!-- 左侧：循环检测 -->
            <div class="card left-card" id="leftCard">
                <div class="card-title">
                    <span>循环检测过程</span>
                    <span class="counter-large" id="totalCounter">0 / 101 次</span>
                </div>

                <!-- 密密麻麻的背景✖ -->
                <div class="bg-watermark" id="bgWatermark"></div>

                <!-- 101个检测格 -->
                <div class="grid-container" id="gridContainer"></div>
            </div>

            <!-- 右侧：有效答案 -->
            <div class="card right-card" id="rightCard">
                <div class="card-title">
                    <span>符合条件答案</span>
                    <span class="counter-large" id="successCounter">0 个</span>
                </div>

                <div class="right-bg-watermark">✔</div>

                <div class="trophy-container" id="trophyContainer">
