                        <path fill="#bdc3c7" id="trophyPath" d="M19 2h-14c-1.1 0-2 .9-2 2v3c0 2.24 1.81 4.07 4.05 4.24l.95 2.76h-2v2h8v-2h-2l.95-2.76c2.24-.17 4.05-2 4.05-4.24v-3c0-1.1-.9-2-2-2zm-12 5v-3h2v3c0 .55-.45 1-1 1s-1-.45-1-1zm10 0c0 .55-.45 1-1 1s-1-.45-1-1v-3h2v3z"/>
                    </svg>
