    <script>
        const gridContainer = document.getElementById('gridContainer');
        const bgWatermark = document.getElementById('bgWatermark');
        const startBtn = document.getElementById('startBtn');
        const compareBtn = document.getElementById('compareBtn');
        const totalCounter = document.getElementById('totalCounter');
        const successCounter = document.getElementById('successCounter');
        const trophyPath = document.getElementById('trophyPath');
        const trophyContainer = document.getElementById('trophyContainer');
        const answerBadge = document.getElementById('answerBadge');
        const mainDisplay = document.getElementById('mainDisplay');
        const thoughtBubble = document.getElementById('thoughtBubble');
        const tooltip = document.getElementById('tooltip');

        const START_NUM = 1000;
        const END_NUM = 1100;
        const TARGET_NUM = 1049;
        const TOTAL_CHECKS = END_NUM - START_NUM + 1;

        let isRunning = false;

        // 1. 初始化背景水印和网格
        function init() {
            gridContainer.innerHTML = '';
            bgWatermark.innerHTML = '';

            // 生成100个背景✖
            for (let i = 0; i < 100; i++) {
                const span = document.createElement('span');
                span.textContent = '✖';
                bgWatermark.appendChild(span);
            }

            // 生成101个待检测格子
            for (let i = START_NUM; i <= END_NUM; i++) {
                const cell = document.createElement('div');
                cell.className = 'cell';
                cell.dataset.number = i;
                cell.textContent = i - START_NUM + 1; // 显示序号

                // 悬停提示
                cell.addEventListener('mouseenter', (e) => {
                    if (cell.classList.contains('checked-fail') || cell.classList.contains('checked-success')) {
                        tooltip.style.opacity = '1';
                        tooltip.textContent = `检测数值: ${i} | 结果: ${i === TARGET_NUM ? '符合条件 ✔' : '不符合 ✖'}`;
                        positionTooltip(e);
                    }
                });

                cell.addEventListener('mousemove', positionTooltip);
                cell.addEventListener('mouseleave', () => {
                    tooltip.style.opacity = '0';
                });

                gridContainer.appendChild(cell);
            }
        }

        function positionTooltip(e) {
            tooltip.style.left = (e.pageX + 10) + 'px';
            tooltip.style.top = (e.pageY + 10) + 'px';
        }

        // 2. 模拟运行动画
        function runSimulation() {
            if (isRunning) return;
            isRunning = true;
            startBtn.disabled = true;
            startBtn.style.opacity = '0.5';

            // 重置状态
            init();
            compareBtn.classList.remove('active');
            mainDisplay.classList.remove('comparing');
            thoughtBubble.classList.remove('show');
            trophyPath.setAttribute('fill', '#bdc3c7');
            trophyContainer.classList.remove('active');
            answerBadge.classList.remove('show');
            successCounter.textContent = '0 个';
            totalCounter.textContent = `0 / ${TOTAL_CHECKS} 次`;

            const cells = gridContainer.children;
            let index = 0;

            function checkNext() {
                if (index >= TOTAL_CHECKS) {
                    // 结束
                    isRunning = false;
                    startBtn.disabled = false;
                    startBtn.style.opacity = '1';
                    startBtn.textContent = '重新模拟';
                    compareBtn.classList.add('active');
                    return;
                }

                const cell = cells[index];
                const currentNum = START_NUM + index;

                totalCounter.textContent = `${index + 1} / ${TOTAL_CHECKS} 次`;

                if (currentNum === TARGET_NUM) {
                    cell.className = 'cell checked-success';
                    cell.textContent = '✔';
                    successCounter.textContent = '1 个';

                    // 奖杯变金色
                    trophyPath.setAttribute('fill', '#f1c40f');
                    trophyContainer.classList.add('active');
                    answerBadge.classList.add('show');
                } else {
                    cell.className = 'cell checked-fail';
                    cell.textContent = '✖';
                }

                // 滚动条自动跟随
                if (index > 30) {
                    gridContainer.scrollTop = cell.offsetTop - gridContainer.offsetTop - 40;
                }

                index++;
                // 快速扫描，前段快，找到答案时稍微停顿增加戏剧效果
                let delay = 15;
                if (currentNum === TARGET_NUM) delay = 400; 
                setTimeout(checkNext, delay);
            }

            checkNext();
        }

        // 3. 对比分析
        function compareAnalysis() {
            mainDisplay.classList.add('comparing');

            // 降低左侧背景✖的透明度，突出对比
            bgWatermark.style.opacity = '0.15';

            // 弹出思考气泡
            setTimeout(() => {
                thoughtBubble.classList.add('show');
            }, 600);
        }

        // 事件绑定
        startBtn.addEventListener('click', runSimulation);
        compareBtn.addEventListener('click', compareAnalysis);

        // 初始化
        init();
    </script>
