                    <!-- 100个微小刻度（用虚线模拟） -->
                    <line x1="60" y1="70" x2="660" y2="70" stroke="#cbd5e1" stroke-width="8" stroke-dasharray="1 5" stroke-linecap="round" opacity="0.8" />

                    <!-- 起点终点标识 -->
                    <text x="60" y="95" class="tick-label">0</text>
                    <text x="360" y="95" class="tick-label">50</text>
                    <text x="660" y="95" class="tick-label">100</text>

                    <!-- 终点宝箱 -->
