                        <!-- 疲惫的眼睛 -->
                        <circle cx="-4" cy="-18" r="1.5" fill="#ef4444" />
                        <circle cx="4" cy="-18" r="1.5" fill="#ef4444" />
                        <!-- 重型盾牌 -->
                        <path d="M -22 -20 L -14 -20 L -18 -5 Z" fill="#475569" stroke="#334155" stroke-width="1.5" />
                        <!-- 汗水 -->
                        <path class="sweat-drop" d="M 12 -22 Q 14 -17 12 -14 Q 10 -17 12 -22" fill="#38bdf8" />
                        <text x="0" y="-36" class="char-label">重甲兵</text>
