                </g>

                <!-- 跑道 B (下方：跳跃检查) -->
                <g transform="translate(0, 160)">
                    <text x="40" y="35" class="track-title">方法 B：跳跃检查（步长 = <tspan id="step-display-val" fill="#2563eb">20</tspan>）</text>
                    <text x="710" y="35" id="label-count-b" class="track-counter" text-anchor="end">检测次数: 0 次</text>

                    <!-- 跑道底线 -->
                    <line x1="60" y1="70" x2="660" y2="70" stroke="#e2e8f0" stroke-width="8" stroke-linecap="round" />
                    <!-- 动态刻度容器 -->
                    <g id="ticks-b"></g>

                    <!-- 起点终点标识 -->
                    <text x="60" y="95" class="tick-label">0</text>
                    <text x="360" y="95" class="tick-label">50</text>
                    <text x="660" y="95" class="tick-label">100</text>

                    <!-- 终点宝箱 -->
                    <g transform="translate(660, 70)">
                        <circle r="16" fill="#fef08a" stroke="#eab308" stroke-width="2" />
