                    <button class="step-btn" data-step="10">10</button>
                    <button class="step-btn active" data-step="20">20</button>
                    <button class="step-btn" data-step="25">25</button>
                    <button class="step-btn" data-step="50">50</button>
                </div>
            </div>
            <div class="action-buttons">
                <button id="btn-start" class="btn btn-primary">开始对比 🚀</button>
                <button id="btn-reset" class="btn btn-secondary">重置 🔄</button>
