    <script>
        // 常量定义
        const TRACK_START_X = 60;
        const TRACK_END_X = 660;
        const TRACK_WIDTH = TRACK_END_X - TRACK_START_X; // 600px

        // 状态变量
        let stepSize = 20;
        let posA = 0; // 0 到 100
        let posB = 0; // 0 到 100
        let countA = 0;
        let countB = 0;
        let isRunning = false;
        let timerA = null;
        let timerB = null;

        // DOM 元素
        const btnStart = document.getElementById('btn-start');
        const btnReset = document.getElementById('btn-reset');
        const stepSelector = document.getElementById('step-selector');
        const stepDisplayVal = document.getElementById('step-display-val');
        const labelCountA = document.getElementById('label-count-a');
        const labelCountB = document.getElementById('label-count-b');
        const runnerA = document.getElementById('runner-a');
        const runnerB = document.getElementById('runner-b');
        const footprintsA = document.getElementById('footprints-a');
        const footprintsB = document.getElementById('footprints-b');
        const ticksBContainer = document.getElementById('ticks-b');
        const medalContainer = document.getElementById('medal-container');

        // 初始化跑道B的刻度
        function drawTicksB() {
            ticksBContainer.innerHTML = '';
            for (let i = 0; i <= 100; i += stepSize) {
                const x = TRACK_START_X + (i / 100) * TRACK_WIDTH;

                // 创建刻度线
                const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                line.setAttribute('x1', x);
                line.setAttribute('y1', '62');
                line.setAttribute('x2', x);
                line.setAttribute('y2', '78');
                line.setAttribute('stroke', '#94a3b8');
                line.setAttribute('stroke-width', '2');
                ticksBContainer.appendChild(line);

                // 创建刻度数字（避开起点和终点，防止重叠）
                if (i !== 0 && i !== 100) {
                    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                    text.setAttribute('x', x);
                    text.setAttribute('y', '95');
                    text.setAttribute('class', 'tick-label');
                    text.textContent = i;
                    ticksBContainer.appendChild(text);
                }
            }
        }

        // 重置状态
        function reset() {
            clearInterval(timerA);
            clearInterval(timerB);
            isRunning = false;

            posA = 0;
            posB = 0;
            countA = 0;
            countB = 0;

            // 还原位置
            runnerA.setAttribute('transform', `translate(${TRACK_START_X}, 70)`);
            runnerB.setAttribute('transform', `translate(${TRACK_START_X}, 70)`);
            runnerB.classList.remove('jump-animation');

            // 还原文本
            labelCountA.textContent = '检测次数: 0 次';
            labelCountB.textContent = '检测次数: 0 次';
            labelCountA.setAttribute('fill', 'var(--text-muted)');
            labelCountB.setAttribute('fill', 'var(--text-muted)');

            // 清空足迹
            footprintsA.innerHTML = '';
            footprintsB.innerHTML = '';

            // 隐藏奖章
            medalContainer.style.display = 'none';
            medalContainer.classList.remove('animate-medal');

            // 启用控制
            btnStart.disabled = false;
            const buttons = stepSelector.querySelectorAll('.step-btn');
            buttons.forEach(btn => btn.disabled = false);
        }

        // 开始动画对比
        function startSimulation() {
            if (isRunning) return;
            isRunning = true;

            btnStart.disabled = true;
            // 禁用步长选择
            const buttons = stepSelector.querySelectorAll('.step-btn');
            buttons.forEach(btn => btn.disabled = true);

            // 1. 重甲兵 A 开始（每 40ms 走 1 步，总共 100 步，约 4 秒到达）
            timerA = setInterval(() => {
                if (posA < 100) {
                    posA += 1;
                    countA += 1;

                    const x = TRACK_START_X + (posA / 100) * TRACK_WIDTH;
                    runnerA.setAttribute('transform', `translate(${x}, 70)`);

                    // 留下足迹
                    addFootprint(footprintsA, x, 70, 'tiny');
                    labelCountA.textContent = `检测次数: ${countA} 次`;
                } else {
                    clearInterval(timerA);
                    labelCountA.textContent = `检测完毕！共检测 ${countA} 次 😫`;
                    labelCountA.setAttribute('fill', 'var(--danger-color)');
                }
            }, 40);

            // 2. 闪电侠 B 开始（每 250ms 跳一步，步长由用户决定）
            timerB = setInterval(() => {
                if (posB < 100) {
                    posB += stepSize;
                    if (posB > 100) posB = 100; // 确保不超过终点
                    countB += 1;

                    const x = TRACK_START_X + (posB / 100) * TRACK_WIDTH;

                    // 触发跳跃动画效果
                    runnerB.classList.remove('jump-animation');
                    void runnerB.offsetWidth; // 触发重绘
                    runnerB.classList.add('jump-animation');

                    runnerB.setAttribute('transform', `translate(${x}, 70)`);

                    // 留下大足迹
                    addFootprint(footprintsB, x, 70, 'large');
                    labelCountB.textContent = `检测次数: ${countB} 次`;
                } else {
                    clearInterval(timerB);
                    labelCountB.textContent = `成功抵达！仅检测 ${countB} 次 ⚡`;
                    labelCountB.setAttribute('fill', 'var(--success-color)');

                    // 弹出大步流星奖章
                    showMedal();
                }
            }, 250);
        }

        // 添加足迹
        function addFootprint(container, x, y, type) {
            const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            circle.setAttribute('cx', x);
            circle.setAttribute('cy', y);

            if (type === 'tiny') {
                circle.setAttribute('r', '3');
                circle.setAttribute('fill', 'var(--danger-color)');
                circle.setAttribute('opacity', '0.6');
            } else {
                circle.setAttribute('r', '6');
                circle.setAttribute('fill', 'var(--success-color)');
                circle.setAttribute('stroke', '#ffffff');
                circle.setAttribute('stroke-width', '1.5');
            }
            container.appendChild(circle);
        }

        // 展示奖章
        function showMedal() {
            medalContainer.style.display = 'block';
            medalContainer.classList.add('animate-medal');
        }

        // 事件监听：步长选择
        stepSelector.addEventListener('click', (e) => {
            if (isRunning) return;
            if (e.target.classList.contains('step-btn')) {
                // 切换高亮
                stepSelector.querySelectorAll('.step-btn').forEach(btn => {
                    btn.classList.remove('active');
                });
                e.target.classList.add('active');

                // 更新步长
                stepSize = parseInt(e.target.getAttribute('data-step'), 10);
                stepDisplayVal.textContent = stepSize;

                // 重新绘制跑道B刻度
                drawTicksB();
            }
        });

        // 事件监听：开始与重置
        btnStart.addEventListener('click', startSimulation);
        btnReset.addEventListener('click', reset);

        // 点击奖章可以将其收起
        medalContainer.addEventListener('click', () => {
            medalContainer.style.display = 'none';
        });

        // 初始化
        drawTicksB();
