  <script>
    // 常量配置
    const START_NUM = 1000;
    const END_NUM = 1030;
    const CELL_WIDTH = 80; // 70px 宽度 + 10px 左右 margin
    const VIEWPORT_WIDTH = 736; // 容器内部可用宽度

    // 目标数字列表 (除以7余6)
    const targets = [];
    for (let i = START_NUM; i <= END_NUM; i++) {
      if (i % 7 === 6) {
        targets.push(i);
      }
    }

    // 状态变量
    let currentStep = 0; // 0: 初始, 1: 1007, 2: 1014, 3: 1021, 4: 1028

    // DOM 元素
    const axisContainer = document.getElementById('axisContainer');
    const svgOverlay = document.getElementById('svgOverlay');
    const formulaDisplay = document.getElementById('formulaDisplay');
    const nextBtn = document.getElementById('nextBtn');
    const resetBtn = document.getElementById('resetBtn');

    // 初始化数轴
    function initAxis() {
      axisContainer.innerHTML = '';
      // 重新加入 SVG
      axisContainer.appendChild(svgOverlay);
      svgOverlay.innerHTML = svgOverlay.innerHTML; // 重置SVG内部元素

      // 计算总宽度并设置给 SVG 和容器
      const totalCells = (END_NUM - START_NUM + 1) + 2; // 加上两边的省略号
      const totalWidth = totalCells * CELL_WIDTH;
      axisContainer.style.width = `${totalWidth}px`;
      svgOverlay.setAttribute('width', totalWidth);

      // 1. 左侧省略号
      createCell('...', 'ellipsis');

      // 2. 数字格子
      for (let i = START_NUM; i <= END_NUM; i++) {
        const isTarget = (i % 7 === 6);
        const cellClass = isTarget ? 'number-cell target' : 'number-cell';
        const cell = createCell(i, cellClass, i);
        if (isTarget) {
          const rem = document.createElement('span');
          rem.className = 'remainder';
          rem.innerText = '余6';
          cell.appendChild(rem);
        }
      }

      // 3. 右侧省略号
      createCell('...', 'ellipsis');

      // 初始定位到最左边
      scrollToIndex(0);
    }

    function createCell(text, className, id) {
      const cell = document.createElement('div');
      cell.className = className;
      cell.innerText = text;
      if (id) cell.id = `cell-${id}`;
      axisContainer.appendChild(cell);
      return cell;
    }

    // 滚动到指定数字，使其居中
    function scrollToNumber(num) {
      const index = num - START_NUM + 1; // 加上左侧省略号的偏移
      scrollToIndex(index);
    }

    function scrollToIndex(index) {
      const cellCenter = index * CELL_WIDTH + (CELL_WIDTH / 2);
      let translateX = (VIEWPORT_WIDTH / 2) - cellCenter;

      // 边界限制
      const maxTranslate = 0;
      const minTranslate = VIEWPORT_WIDTH - (axisContainer.offsetWidth || 2640);
      if (translateX > maxTranslate) translateX = maxTranslate;
      if (translateX < minTranslate) translateX = minTranslate;

      axisContainer.style.transform = `translateX(${translateX}px)`;
    }

    // 绘制跳跃弧线
    function drawJumpArc(fromNum, toNum) {
      const fromIdx = fromNum - START_NUM + 1;
      const toIdx = toNum - START_NUM + 1;

      // 计算坐标 (基于 axisContainer 内部)
      const x1 = fromIdx * CELL_WIDTH + (CELL_WIDTH / 2);
      const x2 = toIdx * CELL_WIDTH + (CELL_WIDTH / 2);
      const y = 140; // 贴近格子顶部
      const cx = (x1 + x2) / 2;
      const cy = 30;  // 弧线顶点高度

      // 创建 Path
      const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
      path.setAttribute("d", `M ${x1} ${y} Q ${cx} ${cy} ${x2} ${y}`);
      path.setAttribute("stroke", "#f97316");
      path.setAttribute("stroke-width", "4");
      path.setAttribute("fill", "none");
      path.setAttribute("marker-end", "url(#arrow)");
      path.setAttribute("class", "draw-arc");

      // 创建标注文字
      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", cx);
      text.setAttribute("y", cy + 30);
      text.setAttribute("fill", "#ea580c");
      text.setAttribute("font-size", "20px");
      text.setAttribute("font-weight", "bold");
      text.setAttribute("text-anchor", "middle");
      text.setAttribute("class", "fade-in-text");
      text.textContent = "+7";

      svgOverlay.appendChild(path);
      svgOverlay.appendChild(text);
    }

    // 更新交互步骤
    function nextStep() {
      if (currentStep < targets.length) {
        currentStep++;
        const activeNum = targets[currentStep - 1];

        // 1. 高亮当前数字
        const cell = document.getElementById(`cell-${activeNum}`);
        if (cell) cell.classList.add('active');

        // 2. 滚动定位
        scrollToNumber(activeNum);

        // 3. 绘制弧线（从第二个目标开始）
        if (currentStep > 1) {
          const prevNum = targets[currentStep - 2];
          drawJumpArc(prevNum, activeNum);
        }

        // 4. 更新公式与教学引导
        updateFormula(activeNum);
      }
    }

    function updateFormula(num) {
      const quotient = Math.floor(num / 7);
      let htmlContent = ``;

      if (currentStep === 1) {
        htmlContent = `<span style="color:#10b981">${num}</span> ÷ 7 = ${quotient} ... <span style="color:#e11d48">6</span> (最小的符合数)`;
        nextBtn.innerText = "寻找下一个数";
      } else if (currentStep === 2) {
        htmlContent = `<span style="color:#10b981">${num}</span> ÷ 7 = ${quotient} ... <span style="color:#e11d48">6</span> (相差：${num} - 1007 = <span style="color:#f97316">7</span>)`;
      } else if (currentStep === 3) {
        htmlContent = `<span style="color:#10b981">${num}</span> ÷ 7 = ${quotient} ... <span style="color:#e11d48">6</span> (再次增加 <span style="color:#f97316">7</span>)`;
      } else if (currentStep === 4) {
        htmlContent = `<span style="color:#10b981">${num}</span> ÷ 7 = ${quotient} ... <span style="color:#e11d48">6</span> (它们构成等差数列！)`;
        nextBtn.innerText = "观察完毕";
        nextBtn.style.backgroundColor = "#10b981";
      }

      formulaDisplay.innerHTML = htmlContent;
    }

    // 重置状态
    function reset() {
      currentStep = 0;
      nextBtn.innerText = "寻找下一个数";
      nextBtn.style.backgroundColor = "#3b82f6";
      formulaDisplay.innerHTML = "准备就绪，点击“寻找下一个数”开始探索";

      // 清除高亮
      const actives = document.querySelectorAll('.number-cell.active');
      actives.forEach(el => el.classList.remove('active'));

      // 清除 SVG 绘制
      const paths = svgOverlay.querySelectorAll('path:not(#arrow path)');
      const texts = svgOverlay.querySelectorAll('text');
      paths.forEach(p => p.remove());
      texts.forEach(t => t.remove());

      scrollToIndex(0);
    }

    // 事件监听
    nextBtn.addEventListener('click', () => {
      if (currentStep < targets.length) {
        nextStep();
      } else {
        reset();
      }
    });

    resetBtn.addEventListener('click', reset);

    // 初始化执行
    initAxis();
  </script>
