<body>

<div class="classroom-container">
    <!-- 头部 -->
    <div class="header">
        <h1>算法优化对比：寻找规律，天生免检！</h1>
        <p>探究：起点设为 1007，步长设为 7，如何让程序运行效率实现火箭般飞跃？</p>
    </div>

    <!-- 主对比区域 -->
    <div class="comparison-grid" id="mainGrid">
        <!-- 方案 A -->
        <div class="scheme-card" id="cardA">
            <div class="scheme-title scheme-a-title">方案 A：常规逐个检查 (步长=1)</div>

            <!-- Scratch 积木 -->
            <div class="code-window">
                <div class="scratch-block block-variable" id="blockA-init">将 [数字] 设为 [1000]</div>
                <div class="scratch-block block-control">重复执行</div>
                <div class="scratch-block block-control block-indent" id="blockA-if">如果 &lt;([数字] 除以 [7] 的余数) = [6]&gt; 那么</div>
                <div class="scratch-block block-motion block-indent-2" id="blockA-add">加入候选列表 (符合条件)</div>
                <div class="scratch-block block-variable block-indent" id="blockA-step">将 [数字] 增加 [1]</div>
            </div>

            <!-- 动画沙盒 -->
            <div class="animation-sandbox" id="sandboxA">
                <div class="conveyor-belt"></div>
                <div class="filter-gate gate-a" id="gateA">
                    <span>检测滤网</span>
                    <span style="font-size: 9px; color: #f1c40f;">÷7 余 6?</span>
                </div>
                <div class="bin bin-fail">废弃数</div>
                <div class="bin bin-success">候选列表</div>
            </div>

            <!-- 统计 -->
            <div class="stats-panel">
                <div class="stat-item"><span>当前检测值:</span><span class="stat-val" id="valA-current">1000</span></div>
                <div class="stat-item"><span>检测次数:</span><span class="stat-val" id="valA-checked">0</span></div>
                <div class="stat-item"><span>符合条件数:</span><span class="stat-val highlight" id="valA-found">0</span></div>
                <div class="stat-item"><span>过滤网状态:</span><span class="stat-val" style="color:var(--danger-color)">频繁拦截</span></div>
            </div>
        </div>

        <!-- 方案 B -->
        <div class="scheme-card" id="cardB">
            <div class="scheme-title scheme-b-title">方案 B：步长优化法 (步长=7)</div>

            <!-- Scratch 积木 -->
            <div class="code-window">
                <div class="scratch-block block-variable" id="blockB-init">将 [数字] 设为 [1007]</div>
                <div class="scratch-block block-control">重复执行</div>
                <div class="scratch-block block-motion block-indent" id="blockB-add" style="background-color: #d4af37; border-left-color: #b8860b;">直接加入候选列表 (免检!)</div>
                <div class="scratch-block block-variable block-indent" id="blockB-step">将 [数字] 增加 [7]</div>
                <div style="color: #7f8c8d; font-size: 11px; margin-left: 15px; margin-top: 5px;">* 省略了“如果”判断滤网！</div>
            </div>

            <!-- 动画沙盒 -->
            <div class="animation-sandbox" id="sandboxB">
                <div class="conveyor-belt"></div>
                <div class="filter-gate gate-b" id="gateB">
                    <span>✨免检通道</span>
                    <span style="font-size: 9px; color: #fff;">天生余6!</span>
                </div>
                <div class="bin bin-success" style="right: auto; left: 50%; transform: translateX(-50%); width: 100px;">候选列表</div>
            </div>

            <!-- 统计 -->
            <div class="stats-panel">
                <div class="stat-item"><span>当前检测值:</span><span class="stat-val" id="valB-current">1007</span></div>
                <div class="stat-item"><span>检测次数:</span><span class="stat-val" id="valB-checked">0</span></div>
                <div class="stat-item"><span>符合条件数:</span><span class="stat-val highlight" id="valB-found">0</span></div>
                <div class="stat-item"><span>过滤网状态:</span><span class="stat-val" style="color:var(--success-color)">✨100%免检</span></div>
            </div>
        </div>
    </div>

    <!-- 控制栏 -->
    <div class="control-bar">
        <div class="btn-group">
            <button class="btn btn-success" id="btnPlay">开始对比运行</button>
            <button class="btn btn-primary" id="btnStep">单步调试</button>
            <button class="btn btn-danger" id="btnReset">重置</button>
        </div>
        <div class="speed-control">
            <span>演示速度:</span>
            <input type="range" class="speed-slider" id="speedSlider" min="1" max="4" step="1" value="1">
            <span id="speedText">1x</span>
        </div>
    </div>

    <!-- 课堂探究问题区 -->
    <div class="quiz-section">
        <div class="quiz-title">💡 课堂思考：为什么方案 B 可以直接省去“除以 7 余 6”的判断滤网？</div>
        <div>当我们把起点设为 1007（已满足余数是6），并且每次增加 7 时：</div>
        <div class="quiz-options">
            <button class="option-btn" data-correct="true">A. 因为 1007 满足条件，每次加 7 得到的数，余数永远都是 6！</button>
            <button class="option-btn" data-correct="false">B. 因为电脑变聪明了，会自动帮我们挑选数字。</button>
            <button class="option-btn" data-correct="false">C. 因为 1007 是一个幸运数字，所以不需要检查。</button>
            <button class="option-btn" data-correct="false">D. 只是碰巧前几个数满足，后面还是需要检查的。</button>
        </div>
        <div class="feedback-text" id="feedback"></div>
    </div>
</div>

<script>
    // 状态变量
    let isRunning = false;
    let speed = 1;
    let timerId = null;

    const state = {
        A: { current: 1000, checked: 0, found: 0, step: 1 },
        B: { current: 1007, checked: 0, found: 0, step: 7 }
    };

    // DOM 元素
    const btnPlay = document.getElementById('btnPlay');
    const btnStep = document.getElementById('btnStep');
    const btnReset = document.getElementById('btnReset');
    const speedSlider = document.getElementById('speedSlider');
    const speedText = document.getElementById('speedText');
    const feedback = document.getElementById('feedback');

    const sandboxA = document.getElementById('sandboxA');
    const sandboxB = document.getElementById('sandboxB');

    // 初始化/重置数据
    function resetSimulation() {
        stopSimulation();
        state.A = { current: 1000, checked: 0, found: 0, step: 1 };
        state.B = { current: 1007, checked: 0, found: 0, step: 7 };
        updateStatsDOM();

        // 清除沙盒中的数字节点
        document.querySelectorAll('.num-node').forEach(node => node.remove());

        // 移除高亮
        document.querySelectorAll('.scratch-block').forEach(b => b.classList.remove('highlight-block'));
        document.getElementById('sandboxA').classList.remove('running');
        document.getElementById('sandboxB').classList.remove('running');
    }

    function updateStatsDOM() {
        document.getElementById('valA-current').innerText = state.A.current;
        document.getElementById('valA-checked').innerText = state.A.checked;
        document.getElementById('valA-found').innerText = state.A.found;

        document.getElementById('valB-current').innerText = state.B.current;
        document.getElementById('valB-checked').innerText = state.B.checked;
        document.getElementById('valB-found').innerText = state.B.found;
    }

    // 单步执行逻辑
    function executeStep() {
        // 方案 A 执行一步
        executeSideA();
        // 方案 B 执行一步
        executeSideB();

        updateStatsDOM();
    }

    function executeSideA() {
        const num = state.A.current;
        const isMatch = (num % 7 === 6);
        state.A.checked++;

        // 积木高亮逻辑
        highlightBlock('A', 'blockA-init', false);
        highlightBlock('A', 'blockA-if', true);

        if (isMatch) {
            state.A.found++;
            setTimeout(() => highlightBlock('A', 'blockA-add', true), 200 / speed);
        } else {
            setTimeout(() => highlightBlock('A', 'blockA-add', false), 200 / speed);
        }
        setTimeout(() => highlightBlock('A', 'blockA-step', true), 400 / speed);

        // 动画节点
        createNode('A', num, isMatch);

        state.A.current += state.A.step;
    }

    function executeSideB() {
        const num = state.B.current;
        // 方案B天生免检，全部都是Match
        const isMatch = true; 
        state.B.checked++;

        // 积木高亮逻辑
        highlightBlock('B', 'blockB-init', false);
        highlightBlock('B', 'blockB-add', true);
        setTimeout(() => highlightBlock('B', 'blockB-step', true), 300 / speed);

        // 动画节点（带火箭特效）
        createNode('B', num, isMatch, true);

        state.B.current += state.B.step;
    }

    function highlightBlock(side, blockId, active) {
        const block = document.getElementById(blockId);
        if (active) {
            block.classList.add('highlight-block');
        } else {
            block.classList.remove('highlight-block');
        }
    }

    // 创建动画数字节点
    function createNode(side, value, isMatch, isRocket = false) {
        const sandbox = side === 'A' ? sandboxA : sandboxB;
        const node = document.createElement('div');
        node.className = 'num-node' + (isRocket ? ' rocket-node' : '');
        node.innerText = value;
        sandbox.appendChild(node);

        const duration = 1000 / speed;

        // 动画阶段 1：生成并移动到滤网
        setTimeout(() => {
            node.style.left = '50%';
            node.style.transform = 'translateX(-50%)';
        }, 50);

        // 动画阶段 2：滤网判定并分流
        setTimeout(() => {
            if (side === 'A') {
                const gate = document.getElementById('gateA');
                if (isMatch) {
                    gate.style.backgroundColor = 'var(--success-color)';
                    node.style.left = '80%';
                    node.style.top = '160px';
                    node.style.opacity = '0';
                } else {
                    gate.style.backgroundColor = 'var(--danger-color)';
                    node.style.left = '20%';
                    node.style.top = '160px';
                    node.style.opacity = '0';
                }
                setTimeout(() => {
                    gate.style.backgroundColor = '';
                }, 300 / speed);
            } else {
                // 方案B直接飞速通过
                node.style.left = '50%';
                node.style.top = '160px';
                node.style.opacity = '0';
            }
        }, duration * 0.5);

        // 动画阶段 3：清理节点
        setTimeout(() => {
            node.remove();
        }, duration * 1.1);
    }

    // 自动运行控制
    function startSimulation() {
        if (isRunning) return;
        isRunning = true;
        btnPlay.innerText = '暂停';
        btnPlay.className = 'btn btn-danger';
        document.getElementById('sandboxA').classList.add('running');
        document.getElementById('sandboxB').classList.add('running');

        const intervalTime = 1200 / speed;
        timerId = setInterval(executeStep, intervalTime);
    }

    function stopSimulation() {
        isRunning = false;
        btnPlay.innerText = '开始对比运行';
        btnPlay.className = 'btn btn-success';
        if (timerId) {
            clearInterval(timerId);
            timerId = null;
        }
        document.getElementById('sandboxA').classList.remove('running');
        document.getElementById('sandboxB').classList.remove('running');
    }

    // 事件监听
    btnPlay.addEventListener('click', () => {
        if (isRunning) {
            stopSimulation();
        } else {
            startSimulation();
        }
    });

    btnStep.addEventListener('click', () => {
        stopSimulation();
        executeStep();
    });

    btnReset.addEventListener('click', resetSimulation);

    speedSlider.addEventListener('input', (e) => {
        speed = parseInt(e.target.value);
        speedText.innerText = speed + 'x';
        if (isRunning) {
            stopSimulation();
            startSimulation();
        }
    });

    // 课堂互动答题
    const optionBtns = document.querySelectorAll('.option-btn');
    optionBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            // 清除之前的状态
            optionBtns.forEach(b => {
                b.classList.remove('correct', 'wrong');
            });

            const isCorrect = btn.getAttribute('data-correct') === 'true';
            if (isCorrect) {
                btn.classList.add('correct');
                feedback.innerHTML = '🎉 答对了！数学规律太神奇了！起点 1007 满足条件，每次加 7 相当于在数学上保持余数不变，所以我们直接省去了繁琐的“如果”判断，效率提升了 7 倍！';
                feedback.style.color = 'var(--success-color)';

                // 方案B卡片触发金色闪烁特效
                document.getElementById('cardB').classList.add('active-b');
            } else {
                btn.classList.add('wrong');
                feedback.innerHTML = '❌ 再想想看，试着算一下：1007 + 7 = 1014，1014 除以 7 的余数是多少？';
                feedback.style.color = 'var(--danger-color)';
                document.getElementById('cardB').classList.remove('active-b');
            }
        });
    });

    // 默认初始化
    resetSimulation();
</script>

</body>
