          </div>
        </div>

        <!-- 变量监视器 -->
        <div class="monitor-section">
          <div class="section-title">变量与状态监视器</div>
          <div class="monitor-grid">
            <div class="monitor-card">
              <span class="monitor-label">当前士兵数 i</span>
              <span class="monitor-value" id="val-i">-</span>
            </div>
            <div class="monitor-card">
              <span class="monitor-label">循环条件 (i <= 1080)</span>
              <span class="monitor-value" id="val-loop">-</span>
            </div>
          </div>
          <div class="monitor-grid" style="grid-template-columns: 1fr 1fr 1fr;">
            <div class="monitor-card">
              <span class="monitor-label">i ÷ 3 余数</span>
              <span class="monitor-value" id="val-r3">-</span>
              <div class="cond-indicator">
                <div class="indicator-dot" id="ind-r3"></div>
                <span>应余 2</span>
              </div>
            </div>
            <div class="monitor-card">
              <span class="monitor-label">i ÷ 5 余数</span>
              <span class="monitor-value" id="val-r5">-</span>
              <div class="cond-indicator">
                <div class="indicator-dot" id="ind-r5"></div>
                <span>应余 3</span>
              </div>
            </div>
            <div class="monitor-card">
              <span class="monitor-label">i ÷ 7 余数</span>
              <span class="monitor-value" id="val-r7">-</span>
              <div class="cond-indicator">
                <div class="indicator-dot" id="ind-r7"></div>
                <span>应余 2</span>
              </div>
            </div>
          </div>
        </div>

        <!-- 运行日志 -->
        <div class="console-section" id="console-log">
          <div class="console-line">> 请先完成右侧的流程图拼图...</div>
        </div>
      </div>

      <!-- 右侧画布面板 -->
      <div class="right-panel">
        <!-- 锁屏遮罩 -->
        <div class="lock-overlay" id="lock-screen">
          <div class="lock-card">
            <div class="lock-icon">🧩</div>
            <h3 style="margin-bottom: 10px;">构建韩信点兵算法</h3>
            <p style="font-size: 14px; color: #7f8c8d; line-height: 1.5;">
              请从左侧零件库中选择正确的算法积木，填入右侧流程图的虚线框中。完整构建算法后即可解锁运行模拟！
            </p>
          </div>
        </div>

        <!-- 流程图 SVG -->
        <svg id="flowchart" viewBox="0 0 600 650">
          <defs>
            <!-- 箭头定义 -->
            <marker id="arrow" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
              <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#7f8c8d" />
