          <line x1="300" y1="355" x2="300" y2="415" stroke="#95a5a6" stroke-width="3" marker-end="url(#arrow)" />
          <text x="315" y="385" fill="#2ecc71" font-size="12" font-weight="bold">是 (True)</text>
          <!-- 余数判断 -> 变量更新 (否) -->
          <path d="M 190 315 L 110 315 L 110 265" fill="none" stroke="#95a5a6" stroke-width="3" marker-end="url(#arrow)" />
          <text x="140" y="305" fill="#e74c3c" font-size="12" font-weight="bold">否 (False)</text>
          <!-- 变量更新 -> 循环条件 -->
          <path d="M 110 215 L 110 150 L 300 150 L 300 165" fill="none" stroke="#95a5a6" stroke-width="3" marker-end="url(#arrow)" />
          <!-- 输出 -> 结束 -->
