    </div>

    <!-- 主工作区 -->
    <div class="workspace">
        <!-- 左栏：并列结构 -->
        <div class="column">
            <div class="column-title">
                <span>并列的“如果...那么”</span>
                <span class="tag tag-parallel">独立判断</span>
            </div>
            <div class="code-area" id="parallel-code">
                <!-- 积木 1 -->
                <div class="scratch-block control-block" id="p-block-1">
                    <div class="header-line">
                        如果 <span class="cond-tag">数字 <span class="val-tag">N</span> 除以 3 余 0</span> 那么
                        <span class="status-indicator" id="p-status-1"></span>
                    </div>
                    <div class="scratch-body">
                        <div class="scratch-block looks-block" id="p-action-1">
                            说出 <span class="val-tag">N</span>
                        </div>
                    </div>
                    <div class="footer-line"></div>
                </div>
                <!-- 积木 2 -->
                <div class="scratch-block control-block" id="p-block-2">
                    <div class="header-line">
                        如果 <span class="cond-tag">数字 <span class="val-tag">N</span> 除以 5 余 0</span> 那么
                        <span class="status-indicator" id="p-status-2"></span>
                    </div>
                    <div class="scratch-body">
                        <div class="scratch-block looks-block" id="p-action-2">
                            说出 <span class="val-tag">N</span>
                        </div>
                    </div>
                    <div class="footer-line"></div>
                </div>
                <!-- 积木 3 -->
                <div class="scratch-block control-block" id="p-block-3">
                    <div class="header-line">
                        如果 <span class="cond-tag">数字 <span class="val-tag">N</span> 除以 2 余 0</span> 那么
                        <span class="status-indicator" id="p-status-3"></span>
                    </div>
                    <div class="scratch-body">
                        <div class="scratch-block looks-block" id="p-action-3">
                            说出 <span class="val-tag">N</span>
                        </div>
                    </div>
                    <div class="footer-line"></div>
                </div>
            </div>
            <!-- 舞台 1 -->
            <div class="stage" id="p-stage">
                <div class="stage-title">🎬 舞台（并列结构运行效果）</div>
                <div class="stage-canvas">
                    <div class="sprite-container">
                        <!-- 简易SVG机器人 -->
                        <svg class="sprite-svg" viewBox="0 0 64 64">
                            <rect x="16" y="16" width="32" height="24" rx="6" fill="#e67e22" stroke="#d35400" stroke-width="2"/>
                            <circle cx="26" cy="26" r="3" fill="#fff"/><circle cx="26" cy="26" r="1.5" fill="#000"/>
                            <circle cx="38" cy="26" r="3" fill="#fff"/><circle cx="38" cy="26" r="1.5" fill="#000"/>
                            <rect x="26" y="32" width="12" height="2" fill="#fff"/>
