                        <div class="speech-bubble" id="p-bubble">说出...</div>
                    </div>
                    <div class="output-stream" id="p-stream">
                        <div class="output-stream-title">角色说出的历史记录</div>
                    </div>
                </div>
            </div>
        </div>

        <!-- 右栏：嵌套结构 -->
        <div class="column">
            <div class="column-title">
                <span>嵌套的“如果...那么”</span>
                <span class="tag tag-nested">层层筛选</span>
            </div>
            <div class="code-area" id="nested-code">
                <!-- 嵌套积木 1 -->
                <div class="scratch-block control-block" id="n-block-1">
