                            <circle cx="38" cy="26" r="3" fill="#fff"/><circle cx="38" cy="26" r="1.5" fill="#000"/>
                            <rect x="26" y="32" width="12" height="2" fill="#fff"/>
                            <line x1="32" y1="16" x2="32" y2="8" stroke="#8e44ad" stroke-width="2"/>
                            <circle cx="32" cy="6" r="3" fill="#ffab19"/>
