                        <div class="speech-bubble" id="n-bubble">说出...</div>
                    </div>
                    <div class="output-stream" id="n-stream">
                        <div class="output-stream-title">角色说出的历史记录</div>
                    </div>
                </div>
            </div>
        </div>
