    <!-- 底部信息栏 -->
    <div class="bottom-bar">
        <div class="log-panel" id="log-panel">
            <div class="log-entry">💡 准备就绪。请选择一个测试数字，然后点击“单步调试”或“批量过滤”开始观察。</div>
        </div>
        <button class="inquiry-btn" id="btn-inquiry">🤔 思考与探究</button>
    </div>
</div>

<!-- 探究弹窗 -->
<div class="modal
